insert into public.docs (path, data) values ('recipes/banana-bread', '{"alt": "Banana bread aux pépites de chocolat tranché, avec une demi-banane sur le dessus", "cat": "Desserts", "groups": [{"g": "", "ing": [{"items": [{"c": "Fruits & légumes", "n": "Bananes", "q": 3, "u": ""}], "t": "3 bananes bien mûres"}, {"items": [{"c": "Placard", "n": "Farine", "q": 210, "u": "g"}], "t": "210 g de farine"}, {"items": [{"c": "Crèmerie & fromages", "n": "Œufs", "q": 2, "u": ""}], "t": "2 œufs"}, {"items": [{"c": "Crèmerie & fromages", "n": "Beurre", "q": 130, "u": "g"}], "t": "130 g de beurre"}, {"items": [{"c": "Placard", "n": "Sucre", "q": 50, "u": "g"}], "t": "50 g de sucre"}, {"items": [{"c": "Épicerie", "n": "Cassonade", "q": 50, "u": "g"}], "t": "50 g de cassonade"}, {"items": [{"c": "Épicerie", "n": "Pépites de chocolat", "q": 150, "u": "g"}], "t": "150 g de pépites de chocolat"}, {"items": [{"c": "Épicerie", "n": "Levure chimique", "q": 0.5, "u": "sachet"}], "t": "½ sachet de levure chimique"}]}], "img": "/photos/banana-bread.jpg", "meta": [["Préparation", "20 min"], ["Cuisson", "45 min"], ["Portions", "8 personnes"]], "notes": ["Matériel : un saladier, un fouet, un moule à cake et une grille.", "Notes : plus les bananes sont mûres, avec de grosses taches noires, plus le goût de banane est présent. Si le dessus dore trop vite, couvrez-le d''une feuille d''aluminium."], "portions": 8, "ptxt": "8 personnes", "source": "D''après Amandise (Journal des Femmes)", "steps": ["Préchauffez le four à 180 °C et beurrez un moule à cake.", "Cassez les œufs dans un saladier, ajoutez le sucre et la cassonade et fouettez jusqu''à ce que le mélange blanchisse.", "Épluchez les bananes, coupez-les en morceaux et écrasez-les grossièrement à la fourchette. Incorporez cette purée à la préparation.", "Faites fondre le beurre coupé en morceaux (casserole ou micro-ondes), versez-le sur la préparation et mélangez.", "Ajoutez la farine et la levure et mélangez jusqu''à obtenir une pâte lisse. Incorporez enfin les pépites de chocolat.", "Versez dans le moule et enfournez environ 45 min. Au bout de 5 à 10 min de cuisson, sortez le cake et faites une entaille sur toute sa longueur avec la pointe d''un couteau, puis remettez-le au four.", "Démoulez et laissez refroidir sur une grille."], "sub": "aux pépites de chocolat", "title": "Banana bread aux pépites de chocolat"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/beignets-chocolat', '{"alt": "Pile de beignets au sucre glace fourrés à la pâte à tartiner", "cat": "Desserts", "groups": [{"g": "", "ing": [{"items": [{"c": "Placard", "n": "Farine", "q": 420, "u": "g"}], "t": "420 g de farine T45"}, {"items": [{"c": "Placard", "n": "Sucre en poudre", "q": 50, "u": "g"}], "t": "50 g de sucre en poudre"}, {"items": [{"c": "Crèmerie & fromages", "n": "Œuf", "q": 1, "u": ""}], "t": "1 œuf + 2 jaunes d''œufs"}, {"items": [{"c": "Crèmerie & fromages", "n": "Beurre", "q": 50, "u": "g"}], "t": "50 g de beurre doux fondu et tiédi"}, {"items": [{"c": "Crèmerie & fromages", "n": "Levure fraîche de boulanger", "q": 20, "u": "g"}], "t": "20 g de levure fraîche de boulanger (ou 7 g de levure sèche)"}, {"items": [{"c": "Épicerie", "n": "Pâte à tartiner", "q": 1, "u": "pot"}], "t": "1 pot de pâte à tartiner (400 g)"}, {"items": [{"c": "Crèmerie & fromages", "n": "Lait", "q": 180, "u": "g"}], "t": "180 g de lait"}, {"items": [{"c": "Placard", "n": "Huile de friture", "q": 600, "u": "ml"}], "t": "600 ml d''huile de friture"}, {"items": [{"c": "Épicerie", "n": "Extrait de vanille", "q": 1, "u": "c. à café"}], "t": "1 c. à café d''extrait de vanille"}, {"items": [{"c": "Épicerie", "n": "Sucre glace", "q": null, "u": ""}], "t": "Sucre glace pour le décor"}, {"items": [{"c": "Placard", "n": "Sel", "q": 0.5, "u": "c. à café"}], "t": "½ c. à café de sel"}]}], "img": "/photos/beignets-chocolat.jpg", "meta": [["Préparation", "20 min"], ["Pousse", "3 h"], ["Portions", "10 beignets"]], "notes": ["Matériel : un robot pâtissier, un emporte-pièce de 8 cm, une poche à douille (douille ronde de 0,9 cm) et un thermomètre de cuisine.", "Notes : les beignets sont meilleurs le jour même, mais se gardent 2 jours dans une boîte hermétique. Tiédissez la pâte à tartiner pour la ramollir."], "portions": 10, "ptxt": "10 beignets", "source": "D''après Lilie Bakery", "steps": ["Faites tiédir le lait (pas trop chaud), émiettez-y la levure, couvrez et laissez reposer 10 min.", "Dans le bol du robot, mélangez la farine, le sucre et le sel, et faites un puits. Ajoutez l''œuf, les jaunes, la vanille, le beurre fondu tiédi puis le mélange lait-levure.", "Pétrissez au crochet environ 10 min : la pâte doit être élastique et ne plus coller aux parois.", "Formez une boule, déposez-la dans un saladier fariné, couvrez et laissez lever 1 h 30 dans un endroit tiède (24-25 °C) : elle doit doubler de volume.", "Dégazez la pâte, abaissez-la sur 1,5 cm et découpez des disques à l''emporte-pièce. Posez-les sur des carrés de papier cuisson, couvrez et laissez pousser encore 1 h 30.", "Chauffez l''huile à 170-175 °C. Faites frire les beignets deux par deux, environ 2 min de chaque côté, jusqu''à une couleur caramel. Égouttez-les sur du papier absorbant.", "Une fois refroidis, percez-les sur le côté et garnissez-les de pâte à tartiner à la poche à douille. Saupoudrez de sucre glace."], "sub": "au chocolat, bien moelleux", "title": "Beignets au chocolat"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/boeuf-bourguignon', '{"alt": "Cocotte en fonte de bœuf bourguignon aux carottes et pommes de terre", "cat": "Plats", "groups": [{"g": "", "ing": [{"items": [{"c": "Viandes & poissons", "n": "Bœuf", "q": 1, "u": "kg"}], "t": "1 kg de bœuf à braiser"}, {"items": [{"c": "Viandes & poissons", "n": "Lardons", "q": 150, "u": "g"}], "t": "150 g de lardons"}, {"items": [{"c": "Fruits & légumes", "n": "Carottes", "q": 2, "u": ""}], "t": "2 carottes"}, {"items": [{"c": "Fruits & légumes", "n": "Oignon", "q": 1, "u": ""}], "t": "1 gros oignon"}, {"items": [{"c": "Fruits & légumes", "n": "Petits oignons", "q": 200, "u": "g"}], "t": "200 g de petits oignons"}, {"items": [{"c": "Fruits & légumes", "n": "Ail", "q": 1, "u": "gousse"}], "t": "1 gousse d''ail"}, {"items": [{"c": "Épicerie", "n": "Vin rouge", "q": 2, "u": "bouteilles"}], "t": "2 bouteilles de vin rouge de Bourgogne"}, {"items": [{"c": "Placard", "n": "Eau", "q": 30, "u": "cl"}], "t": "30 cl d''eau chaude"}, {"items": [{"c": "Placard", "n": "Huile", "q": 2, "u": "c. à soupe"}], "t": "2 c. à soupe d''huile"}, {"items": [{"c": "Épicerie", "n": "Bouillon de bœuf", "q": 1, "u": "cube"}], "t": "1 cube de bouillon de bœuf"}, {"items": [{"c": "Fruits & légumes", "n": "Persil", "q": null, "u": ""}], "t": "Persil haché"}, {"items": [{"c": "Placard", "n": "Sel", "q": null, "u": ""}, {"c": "Placard", "n": "Poivre", "q": null, "u": ""}], "t": "Sel et poivre"}]}], "img": "/photos/boeuf-bourguignon.jpg", "meta": [["Préparation", "20 min"], ["Cuisson", "environ 2 h 45"], ["Portions", "4 personnes"]], "notes": ["Matériel : une grande cocotte avec couvercle.", "Notes : comme tous les plats mijotés, il est encore meilleur réchauffé le lendemain. Servez-le avec des pommes de terre vapeur, des pâtes fraîches ou une purée maison."], "portions": 4, "ptxt": "4 personnes", "source": "", "steps": ["Coupez le bœuf en gros cubes. Émincez la gousse d''ail et le gros oignon, et coupez les carottes en rondelles. Gardez les petits oignons entiers.", "Dans une grande cocotte, faites revenir les lardons 5 min. Ajoutez l''ail, l''oignon et les carottes et poursuivez 5 min. Retirez le tout et réservez.", "Dans la même cocotte, faites dorer les morceaux de bœuf dans l''huile sur toutes les faces, puis remettez le mélange lardons -légumes.", "Délayez le cube de bouillon dans les 30 cl d''eau chaude. Versez le vin rouge et le bouillon dans la cocotte, salez, poivrez et ajoutez le persil. Couvrez et laissez mijoter 2 h 15 à feu doux.", "Ajoutez les petits oignons et poursuivez la cuisson 15 min.", "Servez bien chaud."], "sub": "mijoté au vin de Bourgogne", "title": "Bœuf bourguignon"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/boeuf-carottes', '{"alt": "Cocotte de bœuf aux carottes au thym", "cat": "Plats", "groups": [{"g": "Bœuf aux carottes", "ing": [{"items": [{"c": "Viandes & poissons", "n": "Bœuf", "q": 1, "u": "kg"}], "t": "1 kg de bœuf à braiser"}, {"items": [{"c": "Fruits & légumes", "n": "Carottes", "q": 1, "u": "kg"}], "t": "1 kg de carottes"}, {"items": [{"c": "Fruits & légumes", "n": "Oignon", "q": 1, "u": ""}], "t": "1 oignon"}, {"items": [{"c": "Fruits & légumes", "n": "Échalotes", "q": 3, "u": ""}], "t": "3 échalotes"}, {"items": [{"c": "Épicerie", "n": "Vin blanc", "q": 25, "u": "cl"}], "t": "25 cl de vin blanc"}, {"items": [{"c": "Placard", "n": "Eau", "q": 20, "u": "cl"}], "t": "20 cl d''eau"}, {"items": [{"c": "Placard", "n": "Huile d''olive", "q": 2, "u": "c. à soupe"}], "t": "2 c. à soupe d''huile d''olive"}, {"items": [{"c": "Placard", "n": "Farine", "q": 1, "u": "c. à soupe"}], "t": "1 c. à soupe de farine"}, {"items": [{"c": "Fruits & légumes", "n": "Bouquet garni", "q": 1, "u": ""}], "t": "1 bouquet garni"}, {"items": [{"c": "Placard", "n": "Sel", "q": null, "u": ""}, {"c": "Placard", "n": "Poivre", "q": null, "u": ""}], "t": "Sel et poivre"}]}, {"g": "Purée aux herbes", "ing": [{"items": [{"c": "Fruits & légumes", "n": "Pommes de terre", "q": 8, "u": ""}], "t": "8 pommes de terre"}, {"items": [{"c": "Crèmerie & fromages", "n": "Beurre", "q": 15, "u": "g"}], "t": "15 g de beurre"}, {"items": [{"c": "Crèmerie & fromages", "n": "Lait", "q": 12, "u": "cl"}], "t": "12 cl de lait demi-écrémé"}, {"items": [{"c": "Fruits & légumes", "n": "Basilic", "q": null, "u": ""}, {"c": "Fruits & légumes", "n": "Cerfeuil", "q": null, "u": ""}], "t": "Basilic et cerfeuil"}, {"items": [{"c": "Placard", "n": "Sel", "q": null, "u": ""}, {"c": "Placard", "n": "Poivre", "q": null, "u": ""}], "t": "Sel et poivre"}]}], "img": "/photos/boeuf-carottes.jpg", "meta": [["Préparation", "25 min"], ["Cuisson", "2 h"], ["Portions", "4 personnes"]], "notes": ["Matériel : une cocotte, idéalement en fonte, et une casserole.", "Notes : choisissez du paleron, du rond de gîte, de la macreuse ou de la joue de bœuf. En cocotte en fonte, vous pouvez aussi faire mijoter au four à 160 °C, à couvert : comptez 2 h 30 à 3 h."], "portions": 4, "ptxt": "4 personnes", "source": "D''après CuisineAZ", "steps": ["Dans une cocotte, faites revenir l''oignon émincé et le bœuf coupé en gros dés dans l''huile d''olive. Saupoudrez de farine et mélangez bien.", "Versez le vin blanc et l''eau, ajoutez le bouquet garni, salez et poivrez. Couvrez et laissez mijoter 1 h.", "Épluchez les carottes et coupez-les en rondelles. Épluchez et émincez les échalotes. Ajoutez-les dans la cocotte et poursuivez la cuisson 1 h.", "Pendant ce temps, plongez les pommes de terre épluchées dans une casserole d''eau froide salée, portez à ébullition et faites cuire 25 min. Égouttez-les et écrasez-les à la fourchette.", "En fin de cuisson du bœuf, réchauffez la purée à feu doux avec le basilic et le cerfeuil ciselés. Versez le lait petit à petit en mélangeant, puis ajoutez le beurre. Rectifiez l''assaisonnement."], "sub": "et sa purée aux herbes", "title": "Bœuf aux carottes et purée aux herbes"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/bowl-patate-douce', '{"alt": "Bowl de riz, patate douce rôtie, cranberries, noix de pécan et persil", "cat": "Salades", "groups": [{"g": "", "ing": [{"items": [{"c": "Épicerie", "n": "Riz", "q": 150, "u": "g"}], "t": "150 g de riz (ici, un mélange de 3 riz)"}, {"items": [{"c": "Fruits & légumes", "n": "Patate douce", "q": 200, "u": "g"}], "t": "200 g de patate douce"}, {"items": [{"c": "Fruits & légumes", "n": "Oignon rouge", "q": 1, "u": ""}], "t": "1 oignon rouge"}, {"items": [{"c": "Épicerie", "n": "Cranberries", "q": 40, "u": "g"}], "t": "40 g de cranberries séchées"}, {"items": [{"c": "Épicerie", "n": "Noix de pécan", "q": 40, "u": "g"}], "t": "40 g de noix de pécan"}, {"items": [{"c": "Placard", "n": "Eau", "q": 700, "u": "ml"}], "t": "700 ml d''eau"}, {"items": [{"c": "Placard", "n": "Huile d''olive", "q": 3, "u": "c. à soupe"}], "t": "3 c. à soupe d''huile d''olive"}, {"items": [{"c": "Fruits & légumes", "n": "Thym", "q": 2, "u": "c. à café"}], "t": "2 c. à café de thym"}, {"items": [{"c": "Épicerie", "n": "Origan", "q": 1, "u": "c. à café"}], "t": "1 c. à café d''origan"}, {"items": [{"c": "Épicerie", "n": "Bouillon de légumes", "q": 1, "u": "cube"}], "t": "1 cube de bouillon de légumes"}, {"items": [{"c": "Fruits & légumes", "n": "Persil plat", "q": null, "u": ""}], "t": "Quelques feuilles de persil plat"}, {"items": [{"c": "Placard", "n": "Sel", "q": null, "u": ""}, {"c": "Placard", "n": "Poivre", "q": null, "u": ""}], "t": "Sel et poivre"}]}], "img": "/photos/bowl-patate-douce.jpg", "meta": [["Préparation", "10 min"], ["Cuisson", "20 min"], ["Portions", "2 personnes"]], "notes": ["Matériel : une casserole et une grande poêle.", "Notes : avec un mélange de riz, respectez le temps de cuisson indiqué sur le paquet. Lancez le riz en premier, la patate douce cuit pendant ce temps."], "portions": 2, "ptxt": "2 personnes", "source": "D''après Alix et Anne Grousset, « Mère et fille en cuisine » (Cuisine et Vins de France)", "steps": ["Dans une casserole, portez l''eau à ébullition avec le cube de bouillon. Versez le riz avec 1 c. à café de thym et l''origan, et faites cuire selon le paquet.", "Égouttez le riz, remettez-le dans la casserole, couvrez et réservez.", "Épluchez la patate douce et coupez-la en cubes de 3 à 4 cm. Épluchez l''oignon rouge et émincez-le en lamelles.", "Dans une grande poêle, faites chauffer l''huile d''olive à feu moyen. Ajoutez la patate douce et l''oignon et laissez cuire 15 min en remuant régulièrement. À mi-cuisson, ajoutez le reste de thym, salez et poivrez.", "En fin de cuisson, ajoutez les cranberries et les noix de pécan et laissez cuire 2 min de plus.", "Hors du feu, ajoutez le riz et mélangez. Servez dans des bols, parsemez de persil ciselé et dégustez sans attendre."], "sub": "au riz, aux cranberries et aux noix de pécan", "title": "Bowl de patate douce au riz, cranberries et noix de pécan"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/brownie', '{"alt": "Pile de carrés de brownie au chocolat fondant", "cat": "Desserts", "groups": [{"g": "", "ing": [{"items": [{"c": "Épicerie", "n": "Chocolat noir", "q": 150, "u": "g"}], "t": "150 g de chocolat noir pâtissier 52 %"}, {"items": [{"c": "Épicerie", "n": "Chocolat noir", "q": 80, "u": "g"}], "t": "80 g de chocolat noir haché en grosses pépites"}, {"items": [{"c": "Crèmerie & fromages", "n": "Beurre", "q": 150, "u": "g"}], "t": "150 g de beurre doux"}, {"items": [{"c": "Épicerie", "n": "Cassonade", "q": 100, "u": "g"}], "t": "100 g de cassonade"}, {"items": [{"c": "Placard", "n": "Sucre en poudre", "q": 100, "u": "g"}], "t": "100 g de sucre en poudre"}, {"items": [{"c": "Crèmerie & fromages", "n": "Œufs", "q": 3, "u": ""}], "t": "3 œufs moyens, à température ambiante"}, {"items": [{"c": "Placard", "n": "Farine", "q": 110, "u": "g"}], "t": "110 g de farine T45"}, {"items": [{"c": "Épicerie", "n": "Cacao amer", "q": 30, "u": "g"}], "t": "30 g de cacao amer en poudre"}, {"items": [{"c": "Épicerie", "n": "Extrait de vanille", "q": 1.5, "u": "c. à café"}], "t": "1,5 c. à café d''extrait de vanille"}, {"items": [{"c": "Placard", "n": "Sel", "q": 1, "u": "pincée"}], "t": "1 pincée de sel"}]}], "img": "/photos/brownie.jpg", "meta": [["Préparation", "10 min"], ["Cuisson", "25 à 27 min"], ["Portions", "9 parts"]], "notes": ["Matériel : un batteur électrique, un moule carré de 20 cm et du papier cuisson.", "Notes : se conserve environ 4 jours à température ambiante dans une boîte hermétique. Évitez le réfrigérateur, il durcirait le brownie. Délicieux tiède avec une boule de glace à la vanille."], "portions": 9, "ptxt": "9 parts", "source": "D''après Lilie Bakery", "steps": ["Préchauffez le four à 180 °C (chaleur traditionnelle). Graissez le moule et tapissez-le de papier cuisson.", "Faites fondre au bain-marie les 150 g de chocolat en morceaux et le beurre en dés (ou au micro-ondes, par intervalles de 30 s).", "Ajoutez la cassonade et le sucre au chocolat fondu et mélangez. Incorporez les œufs en fouettant, puis la vanille.", "À part, mélangez la farine, le cacao et le sel, puis ajoutez-les à la pâte. Mélangez juste assez pour ne plus voir de farine.", "Ajoutez les grosses pépites de chocolat et mélangez une dernière fois à la spatule.", "Versez dans le moule et enfournez 25 à 27 min. Une pique en bois ne doit ressortir ni propre ni coulante : les bords sont cuits, le centre un peu moins.", "Laissez tiédir 10 min dans le moule avant de démouler et de couper en carrés."], "sub": "au chocolat fondant", "title": "Brownie chocolat fondant"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/butternut-farcie', '{"alt": "Demi-butternut farcie au chèvre, boulgour, olives et persil dans une assiette", "cat": "Plats", "groups": [{"g": "", "ing": [{"items": [{"c": "Fruits & légumes", "n": "Courge butternut", "q": 1, "u": ""}], "t": "1 courge butternut bio"}, {"items": [{"c": "Épicerie", "n": "Boulgour", "q": 60, "u": "g"}], "t": "60 g de boulgour cru"}, {"items": [{"c": "Crèmerie & fromages", "n": "Chèvre frais", "q": 100, "u": "g"}], "t": "100 g de chèvre frais"}, {"items": [{"c": "Fruits & légumes", "n": "Oignon", "q": 1, "u": ""}], "t": "1 oignon"}, {"items": [{"c": "Fruits & légumes", "n": "Ail", "q": 1, "u": "gousse"}], "t": "1 gousse d''ail"}, {"items": [{"c": "Épicerie", "n": "Olives noires", "q": 30, "u": "g"}], "t": "30 g d''olives noires"}, {"items": [{"c": "Épicerie", "n": "Noisettes", "q": 10, "u": "g"}], "t": "10 g de noisettes concassées"}, {"items": [{"c": "Fruits & légumes", "n": "Thym", "q": 2, "u": "c. à soupe"}], "t": "2 c. à soupe de thym séché"}, {"items": [{"c": "Épicerie", "n": "Bouillon de légumes", "q": 0.5, "u": "cube"}], "t": "½ cube de bouillon de légumes"}, {"items": [{"c": "Fruits & légumes", "n": "Persil", "q": 1, "u": "poignée"}], "t": "1 poignée de persil frais"}, {"items": [{"c": "Placard", "n": "Huile d''olive", "q": null, "u": ""}], "t": "Huile d''olive"}, {"items": [{"c": "Placard", "n": "Sel", "q": null, "u": ""}, {"c": "Placard", "n": "Poivre", "q": null, "u": ""}], "t": "Sel et poivre"}]}], "img": "/photos/butternut-farcie.jpg", "meta": [["Préparation", "25 min"], ["Cuisson", "1 h"], ["Portions", "2 personnes"]], "notes": ["Matériel : une plaque allant au four, une casserole, une sauteuse et un saladier.", "Notes : le temps de cuisson dépend de la taille de la courge. Sa chair doit être bien tendre avant de la prélever."], "portions": 2, "ptxt": "2 personnes", "source": "D''après Alix et Anne Grousset, « Mère et fille en cuisine » (Cuisine et Vins de France)", "steps": ["Préchauffez le four à 180 °C (chaleur tournante). Coupez la courge en deux, évidez-la et striez la chair en croisillons. Posez les moitiés sur une plaque, arrosez d''huile d''olive, salez, poivrez et parsemez de thym. Enfournez 40 min.", "Pendant ce temps, faites cuire le boulgour selon le paquet, en émiettant le bouillon dans l''eau de cuisson.", "Émincez l''oignon et l''ail. Coupez le chèvre en cubes et les olives en morceaux. Ciselez le persil en gardant quelques feuilles.", "Dans une sauteuse, faites revenir l''oignon 4 à 5 min à feu moyen avec un filet d''huile d''olive. Ajoutez le boulgour, l''ail et les olives, laissez revenir 2 à 3 min.", "Versez dans un saladier avec le chèvre et le persil. Prélevez la chair de la courge en laissant 2 cm sur les bords, ajoutez-la au mélange et rectifiez l''assaisonnement.", "Farcissez les demi- butternuts et enfournez de nouveau 10 min.", "À la sortie du four, parsemez des feuilles de persil réservées et des noisettes concassées."], "sub": "au chèvre et au boulgour", "title": "Butternut farcie au chèvre et au boulgour"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/cheesecake-basque', '{"alt": "Cheesecake basque entamé au dessus brûlé", "cat": "Desserts", "groups": [{"g": "", "ing": [{"items": [{"c": "Crèmerie & fromages", "n": "Fromage frais", "q": 400, "u": "g"}], "t": "400 g de fromage frais type Philadelphia"}, {"items": [{"c": "Crèmerie & fromages", "n": "Mascarpone", "q": 400, "u": "g"}], "t": "400 g de mascarpone"}, {"items": [{"c": "Placard", "n": "Sucre en poudre", "q": 200, "u": "g"}], "t": "200 g de sucre en poudre"}, {"items": [{"c": "Crèmerie & fromages", "n": "Œufs", "q": 5, "u": ""}], "t": "5 œufs"}, {"items": [{"c": "Épicerie", "n": "Maïzena", "q": 26, "u": "g"}], "t": "26 g de maïzena"}, {"items": [{"c": "Crèmerie & fromages", "n": "Crème liquide entière", "q": 320, "u": "g"}], "t": "320 g de crème liquide entière 30 %"}, {"items": [{"c": "Épicerie", "n": "Extrait de vanille", "q": 1, "u": "c. à soupe"}], "t": "1 c. à soupe d''extrait de vanille"}, {"items": [{"c": "Crèmerie & fromages", "n": "Beurre", "q": null, "u": ""}], "t": "Un peu de beurre pour le moule"}]}], "img": "/photos/cheesecake-basque.jpg", "meta": [["Préparation", "15 min"], ["Cuisson", "40 à 45 min"], ["Portions", "8 personnes"]], "notes": ["Matériel : un batteur électrique, un moule à charnière de 20 cm et du papier cuisson.", "Notes : sortez tous les ingrédients à l''avance, ils doivent être à température ambiante. Plus on le cuit, moins il est crémeux. Se conserve 4 jours au réfrigérateur."], "portions": 8, "ptxt": "8 personnes", "source": "D''après Lilie Bakery", "steps": ["Préchauffez le four à 225 °C (chaleur traditionnelle). Beurrez légèrement le moule et tapissez-le de deux grands carrés de papier cuisson qui dépassent d''au moins 3 cm.", "Dans un grand récipient, détendez le fromage frais et le mascarpone, ajoutez le sucre et mélangez 3 min.", "Ajoutez les œufs un à un en fouettant bien entre chaque.", "Tamisez la maïzena et incorporez-la en fouettant environ 2 min, sans grumeaux.", "Ajoutez la vanille, puis la crème en filet tout en fouettant, pour un mélange bien lisse.", "Versez dans le moule, tapez-le sur le plan de travail pour chasser les bulles et enfournez 40 à 45 min : le dessus doit être bien bruni et le centre trembler comme un flan.", "Laissez refroidir sur une grille, puis placez au moins 4 h au réfrigérateur, sans couvrir."], "sub": "crémeux et brûlé", "title": "Cheesecake basque"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/cheesecake-new-york', '{"alt": "Part de cheesecake sur base biscuitée dans une assiette bleue", "cat": "Desserts", "groups": [{"g": "", "ing": [{"items": [{"c": "Épicerie", "n": "Gâteaux secs", "q": 250, "u": "g"}], "t": "250 g de gâteaux secs nature ou à la cannelle (Petit Brun, Bastogne, spéculoos)"}, {"items": [{"c": "Crèmerie & fromages", "n": "Faisselle", "q": 500, "u": "g"}], "t": "500 g de faisselle"}, {"items": [{"c": "Crèmerie & fromages", "n": "Beurre", "q": 125, "u": "g"}], "t": "125 g de beurre"}, {"items": [{"c": "Placard", "n": "Sucre", "q": 125, "u": "g"}], "t": "125 g de sucre"}, {"items": [{"c": "Crèmerie & fromages", "n": "Œufs", "q": 2, "u": ""}], "t": "2 œufs"}, {"items": [{"c": "Crèmerie & fromages", "n": "Crème fraîche épaisse", "q": 125, "u": "g"}], "t": "125 g de crème fraîche épaisse"}, {"items": [{"c": "Épicerie", "n": "Extrait de vanille", "q": 1, "u": "c. à café"}], "t": "1 c. à café d''extrait de vanille liquide"}, {"items": [{"c": "Épicerie", "n": "Coulis de fruits rouges", "q": null, "u": ""}], "t": "Coulis de fruits rouges pour le service (facultatif)"}]}], "img": "/photos/cheesecake-new-york.jpg", "meta": [["Cuisson", "40 min"], ["Repos au frais", "8 h minimum"], ["Portions", "8 à 10 parts"]], "notes": ["Matériel : un robot ou un mixeur, et un moule à bord amovible ou en silicone.", "Notes : le cheesecake est encore plus savoureux et onctueux après 1 ou 2 jours au réfrigérateur : préparez-le à l''avance."], "portions": 8, "ptxt": "8 à 10 parts", "source": "", "steps": ["Préchauffez le four à 180 °C (th. 6).", "Cassez les gâteaux secs en deux et mixez-les en miettes pas trop fines, pour garder du croquant.", "Faites fondre le beurre quelques secondes au micro-ondes et mélangez-le aux miettes.", "Étalez ce mélange au fond du moule et tassez-le avec le dos d''une cuillère, en remontant légèrement sur les bords. Placez au réfrigérateur.", "Mélangez la faisselle et la crème fraîche jusqu''à ce que ce soit bien lisse. Ajoutez le sucre, la vanille et les œufs battus, et mélangez jusqu''à obtenir une crème onctueuse.", "Versez sur la base biscuitée, lissez à la spatule et enfournez 40 min : les bords doivent dorer, le centre rester clair.", "Laissez refroidir hors du four, puis placez au réfrigérateur au moins 8 h. Servez avec un coulis de fruits rouges si vous le souhaitez."], "sub": "façon New York, à la faisselle", "title": "Cheesecake new-yorkais"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/clafoutis-cerises', '{"alt": "Clafoutis aux cerises doré dans un plat en verre", "cat": "Desserts", "groups": [{"g": "", "ing": [{"items": [{"c": "Fruits & légumes", "n": "Cerises", "q": 500, "u": "g"}], "t": "500 g de cerises"}, {"items": [{"c": "Placard", "n": "Farine", "q": 100, "u": "g"}], "t": "100 g de farine"}, {"items": [{"c": "Placard", "n": "Sucre", "q": 90, "u": "g"}], "t": "90 g de sucre"}, {"items": [{"c": "Crèmerie & fromages", "n": "Œufs", "q": 4, "u": ""}], "t": "4 œufs"}, {"items": [{"c": "Crèmerie & fromages", "n": "Beurre", "q": 30, "u": "g"}], "t": "30 g de beurre"}, {"items": [{"c": "Épicerie", "n": "Sucre glace", "q": 10, "u": "g"}], "t": "10 g de sucre glace"}, {"items": [{"c": "Crèmerie & fromages", "n": "Lait", "q": 30, "u": "cl"}], "t": "30 cl de lait"}, {"items": [{"c": "Placard", "n": "Sel", "q": 1, "u": "pincée"}], "t": "1 pincée de sel"}]}], "img": "/photos/clafoutis-cerises.jpg", "meta": [["Préparation", "20 min"], ["Cuisson", "40 min"], ["Portions", "6 personnes"]], "notes": ["Matériel : un saladier, un fouet et un moule à tarte ou un plat à gratin.", "Notes : dans la recette traditionnelle, les cerises gardent leur noyau et rendent ainsi moins de jus dans la pâte. Pour la parfumer, ajoutez 1 sachet de sucre vanillé ou 1 c. à café d''extrait de vanille ou d''amande amère. Adaptez le sucre selon vos cerises."], "portions": 6, "ptxt": "6 personnes", "source": "D''après CuisineAZ", "steps": ["Préchauffez le four à 180 °C (th. 6). Faites fondre le beurre.", "Cassez les œufs et battez-les en omelette. Ajoutez la farine, le sucre et le lait, et mélangez jusqu''à obtenir une pâte homogène. Ajoutez la pincée de sel.", "Graissez le moule avec le beurre fondu et étalez les cerises dans le fond.", "Versez la pâte par-dessus les fruits et enfournez pour 35 à 40 min.", "À la sortie du four, saupoudrez toute la surface de sucre glace et dégustez aussitôt."], "sub": "", "title": "Clafoutis aux cerises"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/confiture-mirabelles', '{"alt": "Pot de confiture de mirabelles entouré de mirabelles fraîches", "cat": "Bases", "groups": [{"g": "", "ing": [{"items": [{"c": "Fruits & légumes", "n": "Mirabelles", "q": 1, "u": "kg"}], "t": "1 kg de mirabelles bien mûres"}, {"items": [{"c": "Placard", "n": "Sucre", "q": 600, "u": "g"}], "t": "600 g de sucre cristal ou en poudre"}, {"items": [{"c": "Fruits & légumes", "n": "Jus de citron", "q": 3, "u": "c. à soupe"}], "t": "3 c. à soupe de jus de citron"}, {"items": [{"c": "Épicerie", "n": "Gousse de vanille", "q": 1, "u": ""}], "t": "1 gousse de vanille (facultatif)"}]}], "img": "/photos/confiture-mirabelles.jpg", "meta": [["Préparation", "10 min"], ["Macération", "2 h"], ["Quantité", "2 pots"]], "notes": ["Matériel : 2 pots à confiture, une grande casserole, une cuillère en bois et un mixeur plongeant.", "Notes : la cuisson dure 25 à 30 min selon la maturité des fruits. Une fois ouvert, le pot se garde 10 à 15 jours au réfrigérateur. Fermé et stérilisé, il se conserve plusieurs mois au sec, à l''abri de la chaleur."], "portions": null, "ptxt": "", "source": "D''après Lilie Bakery", "steps": ["Stérilisez les pots : plongez pots et couvercles 10 min dans l''eau bouillante, puis laissez-les égoutter à l''envers sur un linge propre.", "Lavez, coupez en deux et dénoyautez les mirabelles.", "Dans un grand récipient, mélangez les fruits avec le sucre, le jus de citron et les grains de la gousse de vanille. Couvrez et laissez macérer 2 h (ou toute une nuit).", "Versez dans une grande casserole et faites cuire à feu moyen 25 à 30 min, en remuant régulièrement à la cuillère en bois.", "En fin de cuisson, donnez un coup de mixeur plongeant si vous ne voulez pas de gros morceaux.", "Vérifiez la prise : une goutte posée sur une assiette sortie du congélateur doit couler légèrement puis se figer. Sinon, prolongez un peu la cuisson.", "Versez dans les pots stérilisés, fermez-les et laissez-les tiédir à l''envers."], "sub": "de mirabelles, peu sucrée", "title": "Confiture de mirabelles"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/creme-brulee', '{"alt": "Crème brûlée caramélisée dans son ramequin, avec une cuillère", "cat": "Desserts", "groups": [{"g": "", "ing": [{"items": [{"c": "Crèmerie & fromages", "n": "Jaunes d''œufs", "q": 6, "u": ""}], "t": "6 jaunes d''œufs moyens"}, {"items": [{"c": "Placard", "n": "Sucre en poudre", "q": 80, "u": "g"}], "t": "80 g de sucre en poudre"}, {"items": [{"c": "Épicerie", "n": "Cassonade", "q": 60, "u": "g"}], "t": "60 g de cassonade pour caraméliser"}, {"items": [{"c": "Crèmerie & fromages", "n": "Crème liquide entière", "q": 420, "u": "g"}], "t": "420 g de crème liquide entière 30 %"}, {"items": [{"c": "Crèmerie & fromages", "n": "Lait entier", "q": 100, "u": "g"}], "t": "100 g de lait entier"}, {"items": [{"c": "Épicerie", "n": "Gousse de vanille", "q": 1, "u": ""}], "t": "1 gousse de vanille"}]}], "img": "/photos/creme-brulee.jpg", "meta": [["Préparation", "20 min"], ["Cuisson", "30 min"], ["Portions", "4 personnes"]], "notes": ["Matériel : 4 ramequins de 13 cm, un plat à rebord pour le bain-marie, une passoire et un chalumeau de cuisine.", "Notes : prévoyez au moins 4 h de repos au frais, idéalement une nuit. Non caramélisées, les crèmes se gardent 2 jours au réfrigérateur. Avec des ramequins plus hauts, allongez la cuisson."], "portions": 4, "ptxt": "4 personnes", "source": "D''après Lilie Bakery", "steps": ["Préchauffez le four à 140 °C (chaleur traditionnelle).", "Fendez la gousse de vanille et grattez les grains. Mettez grains et gousse dans une casserole avec le lait et la crème, chauffez à feu doux jusqu''à frémissement, puis laissez tiédir.", "Dans un récipient, fouettez à la main les jaunes d''œufs et le sucre. Versez dessus le mélange lait-crème en trois fois, à travers une passoire, en fouettant.", "Placez les ramequins dans un plat à rebord et remplissez-les de crème. Enfournez, puis versez de l''eau chaude dans le plat jusqu''aux 3/4 de la hauteur des ramequins.", "Faites cuire environ 30 min : les crèmes doivent être prises en surface et tremblotantes.", "Laissez tiédir sur une grille, puis placez au réfrigérateur au moins 4 h.", "Juste avant de servir, saupoudrez de cassonade et caramélisez au chalumeau. Dégustez aussitôt."], "sub": "traditionnelle à la vanille", "title": "Crème brûlée"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/crepes', '{"alt": "Pile de crêpes dorées pliées sur une assiette", "cat": "Petit-déj & goûter", "groups": [{"g": "", "ing": [{"items": [{"c": "Placard", "n": "Farine", "q": 250, "u": "g"}], "t": "250 g de farine (T55, T65 ou T80)"}, {"items": [{"c": "Crèmerie & fromages", "n": "Œufs", "q": 4, "u": ""}], "t": "4 œufs frais"}, {"items": [{"c": "Crèmerie & fromages", "n": "Beurre", "q": 50, "u": "g"}], "t": "50 g de beurre fondu (+ un peu pour la poêle)"}, {"items": [{"c": "Crèmerie & fromages", "n": "Lait", "q": 450, "u": "ml"}], "t": "450 ml de lait légèrement tiède"}, {"items": [{"c": "Placard", "n": "Sucre", "q": 2, "u": "c. à soupe"}], "t": "2 c. à soupe de sucre"}, {"items": [{"c": "Épicerie", "n": "Rhum", "q": 2, "u": "c. à soupe"}], "t": "2 c. à soupe de rhum ambré ou de fleur d''oranger (ou ½ verre de bière blonde)"}, {"items": [{"c": "Épicerie", "n": "Extrait de vanille", "q": 1, "u": "c. à soupe"}], "t": "1 c. à soupe d''extrait de vanille (ou 1 sachet de sucre vanillé)"}, {"items": [{"c": "Placard", "n": "Sel", "q": 1, "u": "pincée"}], "t": "1 pincée de sel"}]}], "img": "/photos/crepes.jpg", "meta": [["Préparation", "5 min"], ["Repos", "30 min"], ["Portions", "15 à 20 crêpes"]], "notes": ["Matériel : un grand bol, un fouet et une poêle de 20 cm.", "Notes : pour plus de légèreté, remplacez 50 g de farine par de la fécule de maïs. Le lait à peine tiède évite les grumeaux."], "portions": 15, "ptxt": "15 à 20 crêpes", "source": "D''après Hervé Cuisine", "steps": ["Faites fondre le beurre au micro-ondes et faites tiédir légèrement le lait.", "Dans un grand bol, mélangez la farine tamisée, le sucre et le sel.", "Ajoutez les œufs et le beurre fondu, puis le lait petit à petit en fouettant bien pour éviter les grumeaux.", "Ajoutez le rhum (ou la bière, ou la fleur d''oranger) et la vanille, puis laissez reposer 30 min.", "Faites chauffer une noix de beurre dans la poêle, versez une louche de pâte et faites cuire la crêpe de chaque côté jusqu''à ce qu''elle soit bien dorée.", "Réservez au fur et à mesure dans une assiette couverte d''une feuille d''aluminium pour garder les crêpes chaudes et moelleuses."], "sub": "", "title": "Crêpes moelleuses"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/enchiladas-poulet', '{"alt": "Plat d’enchiladas au poulet nappées de sauce tomate et de cheddar", "cat": "Plats", "groups": [{"g": "", "ing": [{"items": [{"c": "Viandes & poissons", "n": "Poulet", "q": 2, "u": ""}], "t": "2 blancs de poulet"}, {"items": [{"c": "Épicerie", "n": "Tortillas", "q": 8, "u": ""}], "t": "8 tortillas"}, {"items": [{"c": "Fruits & légumes", "n": "Tomates", "q": 3, "u": ""}], "t": "3 tomates"}, {"items": [{"c": "Fruits & légumes", "n": "Poivron", "q": 1, "u": ""}], "t": "1 poivron"}, {"items": [{"c": "Fruits & légumes", "n": "Oignon", "q": 1, "u": ""}], "t": "1 oignon"}, {"items": [{"c": "Fruits & légumes", "n": "Ail", "q": 1, "u": "gousse"}], "t": "1 gousse d''ail"}, {"items": [{"c": "Crèmerie & fromages", "n": "Cheddar râpé", "q": 150, "u": "g"}], "t": "150 g de cheddar râpé"}, {"items": [{"c": "Fruits & légumes", "n": "Citron vert", "q": 1, "u": ""}], "t": "1 citron vert"}, {"items": [{"c": "Placard", "n": "Eau", "q": 0.5, "u": "verre"}], "t": "½ verre d''eau"}, {"items": [{"c": "Placard", "n": "Huile d''olive", "q": 2, "u": "c. à soupe"}], "t": "2 c. à soupe d''huile d''olive"}, {"items": [{"c": "Épicerie", "n": "Paprika", "q": 2, "u": "c. à café"}], "t": "2 c. à café de paprika"}, {"items": [{"c": "Épicerie", "n": "Origan", "q": 2, "u": "c. à café"}], "t": "2 c. à café d''origan"}, {"items": [{"c": "Épicerie", "n": "Cumin", "q": 1, "u": "c. à café"}], "t": "1 c. à café de cumin"}, {"items": [{"c": "Fruits & légumes", "n": "Gingembre", "q": 0.5, "u": "c. à café"}], "t": "½ c. à café de gingembre moulu"}, {"items": [{"c": "Fruits & légumes", "n": "Piment", "q": 0.5, "u": "c. à café"}], "t": "½ c. à café de piment"}]}], "img": "/photos/enchiladas-poulet.jpg", "meta": [["Préparation", "20 min"], ["Cuisson", "30 min"], ["Portions", "8 enchiladas"]], "notes": ["Matériel : une poêle avec couvercle, un mixeur et un plat à four (environ 34 × 24 cm).", "Notes : la recette ne prévoit pas de sel : goûtez la farce et salez si besoin. Vous pouvez préparer le plat la veille et l''enfourner au dernier moment, ou remplacer le poulet par du bœuf ou des légumes."], "portions": 8, "ptxt": "8 enchiladas", "source": "D''après Raphaèle (@raffy_les2quiches) pour MaSpatule", "steps": ["Hachez l''ail, émincez l''oignon et coupez le poivron en fines lamelles.", "Coupez le poulet et 2 tomates en petits morceaux. Mixez la dernière tomate et réservez-la au frais.", "Dans une poêle, faites revenir l''oignon et l''ail dans l''huile d''olive, puis ajoutez le poulet et faites-le revenir.", "Ajoutez les épices (paprika, origan, cumin, gingembre, piment), puis les tomates et le poivron.", "Versez le jus du citron vert et le ½ verre d''eau. Couvrez et laissez cuire 10 min.", "Préchauffez le four à 180 °C. Répartissez la farce dans les 8 tortillas, roulez-les et placez-les dans le plat tapissé de papier cuisson (pour qu''elles n''accrochent pas).", "Nappez de tomate mixée, parsemez de cheddar et enfournez 20 min à 180 °C."], "sub": "au poulet, poivron et cheddar", "title": "Enchiladas au poulet"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/flan-patissier-sans-pate', '{"alt": "Part de flan pâtissier sans pâte sur une assiette blanche", "cat": "Desserts", "groups": [{"g": "", "ing": [{"items": [{"c": "Crèmerie & fromages", "n": "Œufs", "q": 150, "u": "g"}], "t": "150 g d''œufs (environ 3 œufs moyens)"}, {"items": [{"c": "Épicerie", "n": "Cassonade", "q": 150, "u": "g"}], "t": "150 g de cassonade"}, {"items": [{"c": "Épicerie", "n": "Fécule de maïs", "q": 100, "u": "g"}], "t": "100 g de fécule de maïs"}, {"items": [{"c": "Crèmerie & fromages", "n": "Lait", "q": 1, "u": "l"}], "t": "1 l de lait demi-écrémé (1 030 g)"}, {"items": [{"c": "Crèmerie & fromages", "n": "Crème liquide entière", "q": 250, "u": "g"}], "t": "250 g de crème liquide entière (environ 26 cl)"}, {"items": [{"c": "Épicerie", "n": "Arôme vanille", "q": 15, "u": "g"}], "t": "15 g d''arôme vanille (environ 1 c. à soupe)"}]}], "img": "/photos/flan-patissier-sans-pate.jpg", "meta": [["Préparation", "15 min"], ["Cuisson", "30 min"], ["Portions", "8 à 10 parts"]], "notes": ["Matériel : un moule rond de 20 cm sur 5 cm de haut, du papier sulfurisé, un saladier, un fouet et une casserole.", "Notes : préparez-le la veille, il lui faut plusieurs heures au frais pour prendre sa tenue. Se conserve 48 h au réfrigérateur, congélation déconseillée. Le lait entier convient aussi."], "portions": 8, "ptxt": "8 à 10 parts", "source": "D''après MyCake", "steps": ["Préchauffez le four à 200 °C (convection naturelle) et chemisez le moule de papier sulfurisé.", "Dans un grand saladier, fouettez la fécule de maïs, les œufs, la vanille et un tout petit peu de lait jusqu''à obtenir un mélange lisse, sans grumeaux.", "Dans une casserole, portez à ébullition le reste du lait avec la cassonade (le sucre évite la formation d''une peau).", "Versez le lait bouillant en filet sur le mélange en fouettant sans cesse, puis reversez le tout dans la casserole et faites épaissir à feu doux, comme une crème pâtissière.", "Remettez dans le saladier et laissez tiédir un peu. Ajoutez la crème liquide froide et fouettez jusqu''à ce que le mélange soit bien lisse : les éventuels grumeaux disparaissent à cette étape.", "Versez dans le moule, lissez le dessus et tapotez le moule pour chasser les bulles. Enfournez 30 min en bas du four.", "À la sortie, le flan est tremblotant, c''est normal (ajoutez 10 min s''il vous semble trop liquide ou pour plus de couleur). Laissez refroidir, puis placez au réfrigérateur plusieurs heures, idéalement une nuit."], "sub": "sans pâte, ultra crémeux", "title": "Flan pâtissier sans pâte"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/flan-patissier-vanille', '{"alt": "Part de flan pâtissier à la vanille sur pâte sucrée", "cat": "Desserts", "groups": [{"g": "Pâte sucrée", "ing": [{"items": [{"c": "Placard", "n": "Farine", "q": 250, "u": "g"}], "t": "250 g de farine T55"}, {"items": [{"c": "Crèmerie & fromages", "n": "Beurre", "q": 125, "u": "g"}], "t": "125 g de beurre demi-sel mou"}, {"items": [{"c": "Épicerie", "n": "Sucre glace", "q": 90, "u": "g"}], "t": "90 g de sucre glace"}, {"items": [{"c": "Épicerie", "n": "Poudre d''amandes", "q": 30, "u": "g"}], "t": "30 g de poudre d''amandes"}, {"items": [{"c": "Crèmerie & fromages", "n": "Œuf", "q": 1, "u": ""}], "t": "1 œuf"}]}, {"g": "Appareil à flan", "ing": [{"items": [{"c": "Crèmerie & fromages", "n": "Jaunes d''œufs", "q": 6, "u": ""}], "t": "6 jaunes d''œufs (114 g)"}, {"items": [{"c": "Placard", "n": "Sucre", "q": 107, "u": "g"}], "t": "107 g de sucre"}, {"items": [{"c": "Épicerie", "n": "Amidon de maïs", "q": 42, "u": "g"}], "t": "42 g d''amidon de maïs"}, {"items": [{"c": "Crèmerie & fromages", "n": "Beurre", "q": 71, "u": "g"}], "t": "71 g de beurre demi-sel"}, {"items": [{"c": "Crèmerie & fromages", "n": "Lait entier", "q": 500, "u": "g"}], "t": "500 g de lait entier"}, {"items": [{"c": "Crèmerie & fromages", "n": "Crème fraîche épaisse", "q": 142, "u": "g"}], "t": "142 g de crème fraîche épaisse 35 %"}, {"items": [{"c": "Épicerie", "n": "Gousses de vanille", "q": 2, "u": ""}], "t": "2 gousses de vanille"}]}], "img": "/photos/flan-patissier-vanille.jpg", "meta": [["Préparation", "1 h"], ["Cuisson", "45 min"], ["Portions", "8 personnes"]], "notes": ["Matériel : un cercle de 18 cm (4 cm de haut), un rouleau, un fouet et une maryse.", "Notes : la pâte est en trop, congelez le reste pour une autre tarte. Ne fouettez pas trop les jaunes avec l''amidon : un mélange mousseux fait gonfler et déborder le flan. Sortez-le 30 min avant de le servir, il est plus crémeux."], "portions": 8, "ptxt": "8 personnes", "source": "D''après Empreinte Sucrée (recette du chef Quentin Lechat)", "steps": ["Pâte : travaillez le beurre mou, ajoutez le sucre glace, la poudre d''amandes et l''œuf, puis la farine. Étalez entre deux papiers cuisson sur 2 à 3 mm et réservez 1 h au réfrigérateur.", "Beurrez le cercle, découpez un disque de pâte pour le fond et posez-le sur une plaque avec du papier cuisson. Formez les bords avec des bandes de pâte de 4 cm de large. Placez au congélateur.", "Flan : préchauffez le four à 165 °C (chaleur tournante). Portez à ébullition le lait avec la moitié du sucre et les gousses de vanille fendues et grattées.", "Dans un bol, mélangez doucement au fouet le reste du sucre, les jaunes et l''amidon de maïs. Versez le lait chaud dessus, mélangez, reversez dans la casserole et retirez les gousses.", "Portez de nouveau à ébullition et laissez cuire 2 min sans cesser de remuer. Hors du feu, ajoutez la crème et le beurre et mélangez jusqu''à ce que le beurre soit fondu.", "Versez l''appareil encore très chaud dans le fond de tarte congelé et enfournez 45 min.", "Le flan semble pas cuit à la sortie, c''est normal. Laissez-le refroidir au moins 3 h dans son cercle avant de démouler, puis gardez-le au réfrigérateur."], "sub": "à la vanille, sur pâte sucrée", "title": "Flan pâtissier à la vanille"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/galettes-ble-noir', '{"alt": "Galette de sarrasin garnie de saumon fumé et d’un œuf", "cat": "Plats", "groups": [{"g": "La pâte", "ing": [{"items": [{"c": "Épicerie", "n": "Farine de sarrasin", "q": 330, "u": "g"}], "t": "330 g de farine de sarrasin"}, {"items": [{"c": "Crèmerie & fromages", "n": "Œuf", "q": 1, "u": ""}], "t": "1 œuf"}, {"items": [{"c": "Placard", "n": "Eau", "q": 75, "u": "cl"}], "t": "75 cl d''eau froide"}, {"items": [{"c": "Placard", "n": "Gros sel", "q": 10, "u": "g"}], "t": "10 g de gros sel"}, {"items": [{"c": "Placard", "n": "Huile", "q": null, "u": ""}], "t": "Un peu d''huile pour la crêpière"}]}, {"g": "Pour une complète", "ing": [{"items": [{"c": "Crèmerie & fromages", "n": "Beurre", "q": null, "u": ""}], "t": "Beurre"}, {"items": [{"c": "Viandes & poissons", "n": "Jambon", "q": null, "u": ""}], "t": "Jambon"}, {"items": [{"c": "Crèmerie & fromages", "n": "Emmental râpé", "q": null, "u": ""}], "t": "Emmental râpé"}, {"items": [{"c": "Crèmerie & fromages", "n": "Œuf", "q": 1, "u": ""}], "t": "1 œuf par galette"}, {"items": [{"c": "Placard", "n": "Sel", "q": null, "u": ""}, {"c": "Placard", "n": "Poivre", "q": null, "u": ""}], "t": "Sel et poivre"}]}], "img": "/photos/galettes-ble-noir.jpg", "meta": [["Préparation", "20 min"], ["Repos", "1 à 2 h"], ["Portions", "10 galettes"]], "notes": ["Matériel : un saladier, un fouet, une louche, une crêpière et une spatule.", "Notes : pour une version vegan, supprimez l''œuf de la pâte. L''œuf donne surtout une belle coloration à la cuisson."], "portions": 10, "ptxt": "10 galettes", "source": "D''après Marmiton", "steps": ["Dans un saladier, mélangez la farine de sarrasin et le gros sel.", "Versez l''eau en deux ou trois fois en fouettant, jusqu''à obtenir une pâte lisse et épaisse. Ajoutez l''œuf.", "Filmez et laissez reposer 1 à 2 h au réfrigérateur.", "Graissez la crêpière avec un coton imbibé d''huile. Versez une louche de pâte, attendez que la galette colore, décollez-la à la spatule et retournez-la. Laissez cuire encore 1 min environ.", "Pour une complète : beurrez généreusement les deux côtés de la galette, déposez au centre du jambon et de l''emmental râpé, puis cassez un œuf au milieu.", "Quand l''œuf commence à cuire, salez, poivrez et rabattez les bords pour ne laisser voir que le jaune. C''est prêt quand l''œuf est assez cuit."], "sub": "la pâte traditionnelle et la complète", "title": "Galettes de sarrasin"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/gateau-nuage', '{"alt": "Parts de gâteau nuage saupoudrées de sucre glace", "cat": "Desserts", "groups": [{"g": "", "ing": [{"items": [{"c": "Crèmerie & fromages", "n": "Yaourt grec", "q": 500, "u": "g"}], "t": "500 g de yaourt grec"}, {"items": [{"c": "Crèmerie & fromages", "n": "Œufs", "q": 4, "u": ""}], "t": "4 œufs moyens"}, {"items": [{"c": "Placard", "n": "Sucre en poudre", "q": 120, "u": "g"}], "t": "120 g de sucre en poudre"}, {"items": [{"c": "Épicerie", "n": "Maïzena", "q": 90, "u": "g"}], "t": "90 g de maïzena"}, {"items": [{"c": "Épicerie", "n": "Extrait de vanille", "q": 2, "u": "c. à café"}], "t": "2 c. à café d''extrait de vanille"}, {"items": [{"c": "Épicerie", "n": "Levure chimique", "q": 1, "u": "c. à café"}], "t": "1 c. à café de levure chimique"}, {"items": [{"c": "Épicerie", "n": "Coulis", "q": null, "u": ""}], "t": "Coulis de framboise ou d''un autre fruit, pour le service"}, {"items": [{"c": "Crèmerie & fromages", "n": "Beurre", "q": null, "u": ""}], "t": "Un peu de beurre pour le moule"}, {"items": [{"c": "Placard", "n": "Sel", "q": 1, "u": "pincée"}], "t": "1 pincée de sel"}]}], "img": "/photos/gateau-nuage.jpg", "meta": [["Préparation", "15 min"], ["Cuisson", "35 à 40 min"], ["Portions", "6 parts"]], "notes": ["Matériel : un batteur électrique, un moule à charnière de 20 cm et du papier cuisson.", "Notes : se conserve jusqu''à 4 jours au réfrigérateur. Avec un moule de 18 cm, le gâteau sera plus haut. N''ouvrez pas la porte du four pendant la cuisson."], "portions": 6, "ptxt": "6 parts", "source": "D''après Lilie Bakery", "steps": ["Préchauffez le four à 180 °C (chaleur traditionnelle). Beurrez le moule et chemisez-le de papier cuisson (le beurre sert à faire tenir le papier).", "Séparez les blancs des jaunes d''œufs. Fouettez les jaunes avec le sucre jusqu''à ce que le mélange blanchisse.", "À part, mélangez la maïzena, le sel et la levure, puis incorporez-les en trois fois à la pâte, juste assez pour ne plus voir la poudre.", "Ajoutez le yaourt grec et la vanille et mélangez doucement jusqu''à obtenir un mélange homogène.", "Montez les blancs en neige très ferme et incorporez-les délicatement à la spatule, sans les casser.", "Versez dans le moule, lissez et enfournez 35 à 40 min.", "Éteignez le four et entrouvrez la porte pour que le gâteau tiédisse lentement. Servez avec le coulis."], "sub": "au yaourt grec, sans beurre", "title": "Gâteau nuage"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/gaufres', '{"alt": "Gaufres dorées sur une assiette blanche", "cat": "Petit-déj & goûter", "groups": [{"g": "", "ing": [{"items": [{"c": "Placard", "n": "Farine", "q": 500, "u": "g"}], "t": "500 g de farine"}, {"items": [{"c": "Épicerie", "n": "Sucre fin", "q": 300, "u": "g"}], "t": "300 g de sucre fin"}, {"items": [{"c": "Épicerie", "n": "Sucre vanillé", "q": 2, "u": "sachets"}], "t": "2 sachets de sucre vanillé"}, {"items": [{"c": "Crèmerie & fromages", "n": "Margarine", "q": 250, "u": "g"}], "t": "250 g de margarine"}, {"items": [{"c": "Crèmerie & fromages", "n": "Œufs", "q": 4, "u": ""}], "t": "4 œufs"}, {"items": [{"c": "Crèmerie & fromages", "n": "Lait", "q": 25, "u": "cl"}], "t": "25 cl de lait"}, {"items": [{"c": "Épicerie", "n": "Levure chimique", "q": 1, "u": "c. à café"}], "t": "1 c. à café de levure chimique"}, {"items": [{"c": "Placard", "n": "Sel", "q": 1, "u": "pincée"}], "t": "1 pincée de sel"}]}], "img": "/photos/gaufres.jpg", "meta": [["Préparation", "10 min"], ["Cuisson", "2 min 30 / gaufre"], ["Portions", "10 personnes"]], "notes": ["Matériel : un gaufrier et un batteur pour les blancs.", "Notes : la pâte est déjà bien sucrée, inutile de rajouter du sucre au service. Pour 4 à 5 personnes, divisez simplement les quantités par 2. Délicieuses avec une boule de glace à la vanille et quelques rondelles de banane."], "portions": 10, "ptxt": "10 personnes", "source": "D''après Le Journal des Femmes", "steps": ["Préparez tous les ingrédients et séparez les blancs des jaunes d''œufs.", "Dans un saladier, mélangez la levure, le sucre vanillé et le sucre fin.", "Faites fondre la margarine à feu doux et ajoutez-la au mélange. Incorporez le lait, les jaunes d''œufs, la pincée de sel et la farine. Si la pâte devient trop épaisse, alternez la farine avec un peu de blanc d''œuf.", "Battez les blancs d''œufs en neige ferme.", "Incorporez délicatement les blancs en neige à la pâte.", "Graissez bien le gaufrier et déposez une petite louche de pâte sur chaque plaque. Laissez cuire 2 minutes 30, jusqu''à ce que les gaufres soient bien dorées."], "sub": "", "title": "Gaufres maison"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/gougeres', '{"alt": "Bol de gougères dorées au fromage", "cat": "Soupes & entrées", "groups": [{"g": "", "ing": [{"items": [{"c": "Placard", "n": "Farine", "q": 150, "u": "g"}], "t": "150 g de farine"}, {"items": [{"c": "Crèmerie & fromages", "n": "Beurre", "q": 80, "u": "g"}], "t": "80 g de beurre"}, {"items": [{"c": "Crèmerie & fromages", "n": "Œufs", "q": 4, "u": ""}], "t": "4 œufs"}, {"items": [{"c": "Crèmerie & fromages", "n": "Gruyère râpé", "q": 150, "u": "g"}], "t": "150 g de gruyère râpé"}, {"items": [{"c": "Placard", "n": "Eau", "q": 25, "u": "cl"}], "t": "25 cl d''eau"}, {"items": [{"c": "Placard", "n": "Sel", "q": 1, "u": "c. à café"}], "t": "1 c. à café de sel"}]}], "img": "/photos/gougeres.jpg", "meta": [["Préparation", "20 min"], ["Cuisson", "25 min"], ["Portions", "6 personnes"]], "notes": ["Matériel : une casserole, une cuillère en bois, deux cuillères à café (ou une poche à douille lisse moyenne) et une plaque couverte de papier cuisson.", "Notes : travaillez bien la pâte pour y incorporer de l''air : des gougères plates manquent souvent de cuisson ou de fouettage. Elles se congèlent cuites et retrouvent leur croustillant au four. Variante : remplacez le gruyère par du comté."], "portions": 6, "ptxt": "6 personnes", "source": "D''après Lisa Hugon (Journal des Femmes)", "steps": ["Préchauffez le four à 200 °C. Dans une casserole, portez les 25 cl d''eau à ébullition avec le beurre coupé en morceaux et le sel.", "Hors du feu, ajoutez la farine d''un coup. Mélangez vivement, puis faites dessécher la pâte 1 min sur feu doux, sans cesser de remuer.", "Laissez tiédir quelques instants, puis incorporez les œufs un par un en mélangeant bien entre chaque. Ajoutez le gruyère râpé.", "À l''aide de deux cuillères à café, déposez la pâte en petits tas bien séparés sur la plaque.", "Enfournez 25 min en surveillant, sans ouvrir la porte du four pendant la cuisson."], "sub": "au fromage, pour l''apéritif", "title": "Gougères au fromage"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/gratin-aubergines', '{"alt": "Gratin d’aubergines à la mozzarella et à la tomate dans un plat rond", "cat": "Plats", "groups": [{"g": "", "ing": [{"items": [{"c": "Fruits & légumes", "n": "Aubergines", "q": 2, "u": ""}], "t": "2 aubergines"}, {"items": [{"c": "Crèmerie & fromages", "n": "Mozzarella", "q": 250, "u": "g"}], "t": "250 g de mozzarella"}, {"items": [{"c": "Crèmerie & fromages", "n": "Fromage râpé", "q": 50, "u": "g"}], "t": "50 g de fromage râpé"}, {"items": [{"c": "Épicerie", "n": "Coulis de tomates", "q": 500, "u": "ml"}], "t": "500 ml de coulis de tomates"}, {"items": [{"c": "Fruits & légumes", "n": "Herbes de Provence", "q": 2, "u": "c. à soupe"}], "t": "2 c. à soupe rases d''herbes de Provence"}, {"items": [{"c": "Placard", "n": "Huile d''olive", "q": 2, "u": "c. à soupe"}], "t": "2 c. à soupe d''huile d''olive"}, {"items": [{"c": "Placard", "n": "Sel", "q": 1, "u": ""}], "t": "1 bonne pincée de sel"}]}], "img": "/photos/gratin-aubergines.jpg", "meta": [["Préparation", "15 min"], ["Cuisson", "1 h"], ["Portions", "4 personnes"]], "notes": ["Matériel : un petit plat à gratin rond d''environ 22 cm.", "Notes : choisissez des aubergines fermes et pas gorgées d''eau, et gardez bien la chaleur tournante pour éviter un gratin trop liquide. Si elles restent fermes, prolongez la cuisson. Encore meilleur réchauffé le lendemain, à couvert. Congélation déconseillée."], "portions": 4, "ptxt": "4 personnes", "source": "D''après Anne, Papilles & Pupilles", "steps": ["Préchauffez le four à 180 °C (chaleur tournante). Versez l''huile d''olive dans le plat et répartissez-la sur toute la surface.", "Coupez la mozzarella en tranches. Lavez les aubergines, ôtez les extrémités et coupez-les en tranches fines, d''environ ½ cm.", "Déposez la moitié des aubergines dans le plat. Recouvrez de la moitié de la mozzarella, salez légèrement, parsemez d''1 c. à soupe d''herbes de Provence et arrosez avec la moitié du coulis de tomates.", "Faites une deuxième couche avec le reste des aubergines, salez, puis ajoutez le reste de mozzarella, la 2 e cuillère d''herbes et le reste du coulis.", "Parsemez de fromage râpé et enfournez pour 1 h à 180 °C, toujours en chaleur tournante."], "sub": "à la mozzarella et à la tomate", "title": "Gratin d''aubergines"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/gratin-dauphinois-cepes', '{"alt": "Gratin dauphinois aux cèpes dans un plat en fonte", "cat": "Plats", "groups": [{"g": "", "ing": [{"items": [{"c": "Fruits & légumes", "n": "Pommes de terre", "q": 400, "u": "g"}], "t": "400 g de pommes de terre à chair ferme (charlotte, belle-de-Fontenay)"}, {"items": [{"c": "Fruits & légumes", "n": "Cèpes", "q": 250, "u": "g"}], "t": "250 g de cèpes frais"}, {"items": [{"c": "Crèmerie & fromages", "n": "Beurre", "q": 100, "u": "g"}], "t": "100 g de beurre"}, {"items": [{"c": "Fruits & légumes", "n": "Ail", "q": 0.5, "u": ""}], "t": "½ tête d''ail"}, {"items": [{"c": "Crèmerie & fromages", "n": "Crème épaisse", "q": 50, "u": "cl"}], "t": "50 cl de crème épaisse"}, {"items": [{"c": "Fruits & légumes", "n": "Thym", "q": 1, "u": "brin"}], "t": "1 brin de thym"}, {"items": [{"c": "Fruits & légumes", "n": "Laurier", "q": 1, "u": "feuille"}], "t": "1 feuille de laurier"}, {"items": [{"c": "Épicerie", "n": "Noix de muscade", "q": 1, "u": ""}], "t": "1 noix de muscade"}, {"items": [{"c": "Placard", "n": "Sel", "q": null, "u": ""}, {"c": "Placard", "n": "Poivre", "q": null, "u": ""}], "t": "Sel et poivre"}]}], "img": "/photos/gratin-dauphinois-cepes.jpg", "meta": [["Préparation", "40 min"], ["Cuisson", "1 h"], ["Portions", "4 personnes"]], "notes": ["Matériel : une casserole, un chinois (passoire très fine), une poêle et un plat à gratin.", "Accord vin : un pauillac rouge.", "Notes : faites revenir les cèpes en deux fois, d''abord les têtes puis les pieds. La poêle n''est pas surchargée et ils dorent tous bien."], "portions": 4, "ptxt": "4 personnes", "source": "D''après Eric Frechon (Cuisine et Vins de France)", "steps": ["Préchauffez le four à 160 °C (th. 5/6). Grattez et lavez le pied des cèpes pour enlever la terre, puis essuyez-les un à un. Séparez têtes et pieds et émincez-les séparément en lamelles de 5 mm.", "Dans une casserole, portez à ébullition la crème avec l''ail, le thym, le laurier, quelques râpées de muscade, du sel et du poivre. Laissez frémir 5 min à feu doux, puis filtrez au chinois pour ne garder que la crème infusée.", "Dans une poêle, faites fondre une noix de beurre jusqu''à ce qu''il soit noisette. Faites-y revenir les cèpes bien à plat 2 min à feu assez vif, en deux fois.", "Épluchez et lavez les pommes de terre, puis coupez-les en rondelles de 2 mm.", "Dans un plat à gratin, versez une fine couche de crème infusée. Alternez ensuite pommes de terre, crème et cèpes, en terminant par une couche de pommes de terre.", "Enfournez pour 1 h, jusqu''à ce que le dessus soit bien doré, et servez chaud."], "sub": "aux cèpes", "title": "Gratin dauphinois aux cèpes"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/gratin-gnocchis', '{"alt": "Gratin de gnocchis aux épinards et au gorgonzola dans une poêle en fonte", "cat": "Plats", "groups": [{"g": "", "ing": [{"items": [{"c": "Crèmerie & fromages", "n": "Gnocchis frais", "q": 600, "u": "g"}], "t": "600 g de gnocchis frais"}, {"items": [{"c": "Fruits & légumes", "n": "Épinards", "q": 300, "u": "g"}], "t": "300 g de jeunes pousses d''épinards fraîches"}, {"items": [{"c": "Crèmerie & fromages", "n": "Gorgonzola", "q": 150, "u": "g"}], "t": "150 g de gorgonzola"}, {"items": [{"c": "Crèmerie & fromages", "n": "Parmesan", "q": 20, "u": "g"}], "t": "20 g de parmesan râpé"}, {"items": [{"c": "Crèmerie & fromages", "n": "Crème liquide", "q": 200, "u": "ml"}], "t": "200 ml de crème liquide"}, {"items": [{"c": "Placard", "n": "Sel", "q": null, "u": ""}, {"c": "Placard", "n": "Poivre", "q": null, "u": ""}], "t": "Sel et poivre"}]}], "img": "/photos/gratin-gnocchis.jpg", "meta": [["Préparation", "15 min"], ["Cuisson", "20 min"], ["Portions", "4 personnes"]], "notes": ["Matériel : une poêle avec couvercle, deux casseroles et un plat à gratin.", "Notes : gardez 50 g de gorgonzola pour le dessus. Réparti en petits morceaux juste avant d''enfourner, il donne de belles touches fondantes après cuisson."], "portions": 4, "ptxt": "4 personnes", "source": "D''après Stéphanie Iguna, « À table sans se ruiner » (Cuisine et Vins de France)", "steps": ["Préchauffez le four à 180 °C. Dans une poêle chaude sans matière grasse, faites revenir les épinards 5 minutes à couvert. Salez et poivrez légèrement.", "Pendant ce temps, faites cuire les gnocchis dans une casserole d''eau bouillante salée. Égouttez-les dès qu''ils remontent à la surface.", "Dans une casserole, faites fondre 100 g de gorgonzola à feu doux avec la crème liquide, en mélangeant jusqu''à obtenir une sauce lisse. Poivrez légèrement.", "Dans un plat à gratin, disposez les gnocchis et les épinards. Versez la sauce au gorgonzola par-dessus en veillant à bien enrober les gnocchis.", "Répartissez les 50 g de gorgonzola restants coupés en petits morceaux, puis saupoudrez de parmesan râpé.", "Enfournez pour 20 minutes, jusqu''à ce que le dessus soit doré et légèrement croustillant. Servez chaud et dégustez sans attendre."], "sub": "aux épinards et au gorgonzola", "title": "Gratin de gnocchis aux épinards et au gorgonzola"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/gratin-poireaux-reblochon', '{"alt": "Gratin de poireaux gratiné au reblochon dans un plat en terre", "cat": "Plats", "groups": [{"g": "", "ing": [{"items": [{"c": "Fruits & légumes", "n": "Poireaux", "q": 4, "u": ""}], "t": "4 poireaux"}, {"items": [{"c": "Crèmerie & fromages", "n": "Reblochon", "q": 1, "u": ""}], "t": "1 reblochon"}, {"items": [{"c": "Fruits & légumes", "n": "Échalotes", "q": 2, "u": ""}], "t": "2 échalotes"}, {"items": [{"c": "Crèmerie & fromages", "n": "Crème fraîche", "q": 2, "u": "c. à soupe"}], "t": "2 c. à soupe de crème fraîche"}, {"items": [{"c": "Crèmerie & fromages", "n": "Beurre", "q": null, "u": ""}], "t": "Un peu de beurre"}, {"items": [{"c": "Placard", "n": "Sel", "q": null, "u": ""}, {"c": "Placard", "n": "Poivre", "q": null, "u": ""}], "t": "Sel et poivre"}]}], "img": "/photos/gratin-poireaux-reblochon.jpg", "meta": [["Préparation", "10 min"], ["Cuisson", "40 min"], ["Portions", "4 personnes"]], "notes": ["Matériel : une casserole, une poêle et un plat à gratin.", "Notes : seuls les blancs de poireaux sont utilisés, gardez les verts pour une soupe. Égouttez-les bien pour éviter un gratin trop liquide. Variante des lecteurs : 1 c. à café de cumin dans la crème, ou un peu de chorizo grillé."], "portions": 4, "ptxt": "4 personnes", "source": "D''après La cuillère aux mille délices (Journal des Femmes)", "steps": ["Préchauffez le four à 200 °C.", "Coupez les blancs de poireaux en rondelles et faites-les cuire 10 min dans une casserole d''eau salée. Égouttez-les bien.", "Dans une poêle, faites revenir à feu doux les échalotes émincées dans un peu de beurre, puis ajoutez les poireaux.", "Versez la crème fraîche, salez, poivrez et mélangez bien.", "Versez la préparation dans un plat à gratin et répartissez dessus le reblochon coupé en lamelles.", "Enfournez 20 min, jusqu''à ce que le fromage soit fondu et doré."], "sub": "au reblochon", "title": "Gratin de poireaux au reblochon"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/guacamole', '{"alt": "Bol de guacamole avec des tortillas chips", "cat": "Soupes & entrées", "groups": [{"g": "", "ing": [{"items": [{"c": "Fruits & légumes", "n": "Avocats", "q": 3, "u": ""}], "t": "3 avocats bien mûrs"}, {"items": [{"c": "Fruits & légumes", "n": "Tomates", "q": 2, "u": ""}], "t": "2 tomates"}, {"items": [{"c": "Fruits & légumes", "n": "Oignon", "q": 0.5, "u": ""}], "t": "½ oignon"}, {"items": [{"c": "Fruits & légumes", "n": "Citron vert", "q": 1, "u": ""}], "t": "1 citron vert (ou jaune)"}, {"items": [{"c": "Fruits & légumes", "n": "Coriandre", "q": 1, "u": "c. à soupe"}], "t": "1 c. à soupe de feuilles de coriandre"}, {"items": [{"c": "Épicerie", "n": "Cumin", "q": 1, "u": ""}], "t": "1 grosse pincée de cumin"}, {"items": [{"c": "Épicerie", "n": "Tabasco", "q": 3, "u": ""}], "t": "3 gouttes de Tabasco (ou 1 pincée de piment de Cayenne)"}, {"items": [{"c": "Placard", "n": "Sel", "q": 1, "u": "pincée"}], "t": "1 pincée de sel"}]}], "img": "/photos/guacamole.jpg", "meta": [["Préparation", "15 min"], ["Cuisson", "sans cuisson"], ["Portions", "6 personnes"]], "notes": ["Matériel : un saladier et une fourchette (ou un blender pour une version lisse).", "Notes : si vous le préparez à l''avance, posez un film alimentaire directement au contact du guacamole pour qu''il ne noircisse pas. Sans coriandre, remplacez-la par du persil ou supprimez-la. À servir avec des tortillas chips, des crudités, ou avec des tacos."], "portions": 6, "ptxt": "6 personnes", "source": "D''après Anne, Papilles & Pupilles", "steps": ["Pelez les tomates, épépinez-les et coupez-les en petits cubes. Pelez l''oignon et coupez-le aussi en petits cubes.", "Lavez, séchez et ciselez finement la coriandre. Pressez le citron.", "Fendez les avocats en deux, ôtez le noyau, récupérez la chair à la cuillère et écrasez-la grossièrement à la fourchette.", "Ajoutez le jus de citron, le sel, le Tabasco et le cumin, et mélangez.", "Ajoutez les dés d''oignon et de tomate et la coriandre ciselée. Mélangez à nouveau, goûtez et rectifiez l''assaisonnement.", "Pour une texture lisse, passez simplement le tout au blender."], "sub": "avec des morceaux, comme au Mexique", "title": "Guacamole"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/hachis-parmentier', '{"alt": "Hachis parmentier gratiné entamé, dans un plat à tarte", "cat": "Plats", "groups": [{"g": "La purée", "ing": [{"items": [{"c": "Fruits & légumes", "n": "Pommes de terre", "q": 1, "u": "kg"}], "t": "1 kg de pommes de terre"}, {"items": [{"c": "Crèmerie & fromages", "n": "Beurre", "q": 50, "u": "g"}], "t": "50 g de beurre"}, {"items": [{"c": "Crèmerie & fromages", "n": "Gruyère râpé", "q": 100, "u": "g"}], "t": "100 g de gruyère râpé"}, {"items": [{"c": "Crèmerie & fromages", "n": "Lait", "q": 20, "u": "cl"}], "t": "20 cl de lait"}, {"items": [{"c": "Crèmerie & fromages", "n": "Crème", "q": 1, "u": "c. à soupe"}], "t": "1 c. à soupe de crème"}, {"items": [{"c": "Épicerie", "n": "Muscade", "q": 1, "u": "c. à café"}], "t": "1 c. à café de muscade"}, {"items": [{"c": "Placard", "n": "Sel", "q": 1, "u": "c. à café"}], "t": "1 c. à café de sel"}, {"items": [{"c": "Épicerie", "n": "Chapelure", "q": null, "u": ""}], "t": "Facultatif : chapelure ou polenta pour gratiner"}]}, {"g": "Le hachis", "ing": [{"items": [{"c": "Viandes & poissons", "n": "Bœuf haché", "q": 500, "u": "g"}], "t": "500 g de bœuf haché"}, {"items": [{"c": "Fruits & légumes", "n": "Carotte", "q": 1, "u": ""}], "t": "1 carotte"}, {"items": [{"c": "Fruits & légumes", "n": "Oignon", "q": 1, "u": ""}], "t": "1 oignon"}, {"items": [{"c": "Fruits & légumes", "n": "Échalote", "q": 1, "u": ""}], "t": "1 échalote"}, {"items": [{"c": "Fruits & légumes", "n": "Ail", "q": 2, "u": "gousses"}], "t": "2 gousses d''ail"}, {"items": [{"c": "Crèmerie & fromages", "n": "Beurre", "q": 25, "u": "g"}], "t": "25 g de beurre"}, {"items": [{"c": "Placard", "n": "Sel", "q": 1, "u": "c. à café"}], "t": "1 c. à café de sel"}, {"items": [{"c": "Placard", "n": "Poivre", "q": 1, "u": "c. à café"}], "t": "1 c. à café de poivre"}]}], "img": "/photos/hachis-parmentier.jpg", "meta": [["Préparation", "10 min"], ["Cuisson", "1 h"], ["Portions", "6 personnes"]], "notes": ["Matériel : un moulin à légumes ou un presse-purée, une sauteuse et un plat à gratin.", "Notes : pour la viande, choisissez de la macreuse, de l''aloyau ou du jarret, ou du veau pour plus de douceur. Se prépare la veille : réchauffez-le au four à 170 °C. Se congèle 2 mois, décongélation au réfrigérateur, puis four moyen sous papier d''aluminium."], "portions": 6, "ptxt": "6 personnes", "source": "D''après Cécile Rocks (Journal des Femmes)", "steps": ["Hachez l''oignon, l''ail et l''échalote. Épluchez la carotte et taillez-la en brunoise très fine. Épluchez les pommes de terre et coupez-les en petits morceaux.", "Faites cuire les pommes de terre environ 30 min à l''eau salée (ou dans du lait, en surveillant le débordement).", "Faites revenir la carotte 1 min dans le beurre, puis ajoutez l''oignon, l''ail et l''échalote et laissez encore 1 min.", "Ajoutez le bœuf haché, salez, poivrez et laissez cuire 10 min en remuant.", "Passez les pommes de terre au moulin à légumes ou au presse-purée. Ajoutez le beurre, le lait, la crème, la muscade et le sel, et mélangez rapidement.", "Disposez la viande dans le plat à gratin, recouvrez de purée et terminez par le gruyère. Pour un dessus plus croustillant, parsemez d''un peu de chapelure ou de polenta. Passez 10 min au four très chaud (environ 220 °C), puis 2 min sous le gril."], "sub": "la recette traditionnelle", "title": "Hachis parmentier"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/lasagnes-bolognaise-vegetariennes', '{"alt": "Lasagnes bolognaise aux lentilles gratinées, au basilic", "cat": "Plats", "groups": [{"g": "Bolognaise aux lentilles", "ing": [{"items": [{"c": "Épicerie", "n": "Lentilles beluga", "q": 200, "u": "g"}], "t": "200 g de lentilles beluga ou du Puy"}, {"items": [{"c": "Fruits & légumes", "n": "Carottes", "q": 2, "u": ""}], "t": "2 carottes"}, {"items": [{"c": "Fruits & légumes", "n": "Céleri", "q": 2, "u": ""}], "t": "2 bâtonnets de céleri"}, {"items": [{"c": "Fruits & légumes", "n": "Oignon", "q": 1, "u": ""}], "t": "1 oignon jaune"}, {"items": [{"c": "Fruits & légumes", "n": "Champignons", "q": 80, "u": "g"}], "t": "80 g de champignons"}, {"items": [{"c": "Fruits & légumes", "n": "Ail", "q": 3, "u": "gousses"}], "t": "3 gousses d''ail"}, {"items": [{"c": "Épicerie", "n": "Cerneaux de noix", "q": 65, "u": "g"}], "t": "65 g de cerneaux de noix"}, {"items": [{"c": "Épicerie", "n": "Tomates concassées", "q": 800, "u": "g"}], "t": "800 g de tomates concassées"}, {"items": [{"c": "Épicerie", "n": "Vin rouge", "q": 120, "u": "ml"}], "t": "120 ml de vin rouge (ou balsamique)"}, {"items": [{"c": "Épicerie", "n": "Bouillon de légumes", "q": 360, "u": "ml"}], "t": "360 ml de bouillon de légumes"}, {"items": [{"c": "Placard", "n": "Huile d''olive", "q": 3, "u": "c. à soupe"}], "t": "3 c. à soupe d''huile d''olive"}, {"items": [{"c": "Épicerie", "n": "Origan", "q": 1, "u": "c. à soupe"}], "t": "1 c. à soupe d''origan"}, {"items": [{"c": "Fruits & légumes", "n": "Laurier", "q": 1, "u": "feuille"}], "t": "1 feuille de laurier"}, {"items": [{"c": "Placard", "n": "Sel", "q": null, "u": ""}, {"c": "Placard", "n": "Poivre", "q": null, "u": ""}], "t": "Sel et poivre"}]}, {"g": "Montage", "ing": [{"items": [{"c": "Épicerie", "n": "Lasagnes", "q": 9, "u": "feuilles"}], "t": "9 feuilles de lasagnes précuites"}, {"items": [{"c": "Crèmerie & fromages", "n": "Fromage râpé", "q": 150, "u": "g"}], "t": "150 g de fromage râpé"}, {"items": [{"c": "Fruits & légumes", "n": "Basilic", "q": null, "u": ""}], "t": "Facultatif : basilic"}]}, {"g": "Béchamel", "ing": [{"items": [{"c": "Crèmerie & fromages", "n": "Beurre", "q": 140, "u": "g"}], "t": "140 g de beurre doux"}, {"items": [{"c": "Placard", "n": "Farine", "q": 140, "u": "g"}], "t": "140 g de farine"}, {"items": [{"c": "Crèmerie & fromages", "n": "Lait", "q": 1, "u": "l"}], "t": "1 l de lait demi-écrémé chaud"}, {"items": [{"c": "Épicerie", "n": "Muscade", "q": 1, "u": "pincée"}], "t": "1 pincée de muscade, sel, poivre"}]}], "img": "/photos/lasagnes-bolognaise-vegetariennes.jpg", "meta": [["Préparation", "1 h"], ["Cuisson", "35 à 40 min"], ["Portions", "8 personnes"]], "notes": ["Matériel : robot mixeur, cocotte, casserole, plat de 33 × 23 cm.", "Notes : pas de trempage pour les lentilles, rincez-les simplement. La bolognaise se prépare à l''avance et se congèle 3 mois."], "portions": 8, "ptxt": "8 personnes", "source": "D''après Delphine Fortin (Del''s cooking twist)", "steps": ["Au robot, pulsez l''oignon, les carottes et le céleri pour les émincer finement, sans les réduire en purée. Hachez les noix en gardant un peu de texture.", "Dans une cocotte, faites revenir les légumes et les champignons en morceaux 5 min dans l''huile d''olive. Ajoutez les noix, l''origan et l''ail, quelques minutes. Salez, poivrez.", "Versez le vin rouge et laissez évaporer. Ajoutez le laurier, les lentilles, le bouillon et les tomates. Portez à ébullition, puis laissez mijoter 30 min à feu très doux, en ajoutant du bouillon si la sauce épaissit trop.", "Béchamel : faites fondre le beurre, ajoutez la farine d''un coup en fouettant, puis le lait chaud petit à petit, environ 10 min, jusqu''à ce qu''elle soit crémeuse. Muscade, sel, poivre.", "Préchauffez le four à 180 °C et huilez le plat. Un peu de béchamel au fond, puis lasagnes, bolognaise, béchamel, fromage. Répétez et finissez par lasagnes, béchamel et fromage (3 couches).", "Enfournez 30 à 35 min, puis quelques minutes sous le gril en surveillant. Ajoutez le basilic et servez chaud."], "sub": "bolognaise aux lentilles et champignons", "title": "Lasagnes bolognaise végétariennes"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/lasagnes-bolognaise', '{"alt": "Part de lasagnes bolognaise gratinées", "cat": "Plats", "groups": [{"g": "Lasagnes", "ing": [{"items": [{"c": "Épicerie", "n": "Lasagnes", "q": 8, "u": ""}], "t": "8 plaques de lasagnes (fraîches ou sans précuisson)"}, {"items": [{"c": "Viandes & poissons", "n": "Bœuf haché", "q": 300, "u": "g"}], "t": "300 g de bœuf haché"}, {"items": [{"c": "Épicerie", "n": "Pulpe de tomate", "q": 800, "u": "g"}], "t": "800 g de pulpe de tomate (ou 500 g de tomates fraîches)"}, {"items": [{"c": "Fruits & légumes", "n": "Oignon", "q": 1, "u": ""}], "t": "1 oignon"}, {"items": [{"c": "Fruits & légumes", "n": "Ail", "q": 1, "u": "gousse"}], "t": "1 gousse d''ail"}, {"items": [{"c": "Crèmerie & fromages", "n": "Emmental râpé", "q": 100, "u": "g"}], "t": "100 g d''emmental râpé"}, {"items": [{"c": "Crèmerie & fromages", "n": "Parmesan râpé", "q": null, "u": ""}], "t": "Parmesan râpé (pour le dessus)"}, {"items": [{"c": "Placard", "n": "Huile d''olive", "q": 2, "u": "c. à soupe"}], "t": "2 c. à soupe d''huile d''olive"}, {"items": [{"c": "Fruits & légumes", "n": "Herbes", "q": 1, "u": "c. à soupe"}], "t": "1 c. à soupe d''herbes (origan, thym, basilic)"}, {"items": [{"c": "Placard", "n": "Sucre", "q": 2, "u": "morceaux"}], "t": "2 morceaux de sucre"}, {"items": [{"c": "Placard", "n": "Sel", "q": null, "u": ""}, {"c": "Placard", "n": "Poivre", "q": null, "u": ""}], "t": "Sel et poivre"}, {"items": [{"c": "Fruits & légumes", "n": "Champignons de Paris", "q": null, "u": ""}], "t": "Facultatif : champignons de Paris"}]}, {"g": "Béchamel", "ing": [{"items": [{"c": "Crèmerie & fromages", "n": "Beurre", "q": 70, "u": "g"}], "t": "70 g de beurre"}, {"items": [{"c": "Placard", "n": "Farine", "q": 70, "u": "g"}], "t": "70 g de farine"}, {"items": [{"c": "Crèmerie & fromages", "n": "Lait", "q": 50, "u": "cl"}], "t": "50 cl de lait"}, {"items": [{"c": "Épicerie", "n": "Noix de muscade", "q": 1, "u": "pincée"}], "t": "1 pincée de noix de muscade"}, {"items": [{"c": "Placard", "n": "Sel", "q": null, "u": ""}, {"c": "Placard", "n": "Poivre", "q": null, "u": ""}], "t": "Sel et poivre"}]}], "img": "/photos/lasagnes-bolognaise.jpg", "meta": [["Préparation", "20 min"], ["Cuisson", "environ 1 h 15"], ["Portions", "6 personnes"]], "notes": ["Matériel : une sauteuse, une poêle, une casserole, une écumoire et un plat à gratin.", "Notes : le sucre adoucit l''acidité de la pulpe en conserve. Les amateurs peuvent ajouter des lamelles de champignons de Paris au moment du montage."], "portions": 6, "ptxt": "6 personnes", "source": "D''après la Rédaction (Journal des Femmes)", "steps": ["Émincez l''oignon et l''ail. Faites-les revenir avec 1 c. à soupe d''huile d''olive, 1 à 2 min à feu vif, puis à feu doux jusqu''à ce qu''ils soient translucides et dorés.", "Ajoutez la pulpe de tomate, salez, poivrez, ajoutez les herbes et le sucre. Laissez mijoter 20 min à feu doux, puis mixez ou non.", "Pendant ce temps, faites dorer le bœuf haché 3 à 5 min dans le reste d''huile d''olive. Salez, poivrez, puis ajoutez-le à la sauce à l''aide d''une écumoire pour laisser le gras dans la poêle.", "Béchamel : faites fondre le beurre, ajoutez la farine hors du feu et mélangez. Versez le lait très progressivement, puis laissez épaissir quelques minutes sur feu doux. Salez, poivrez et ajoutez la muscade.", "Préchauffez le four à 165 °C. Dans un plat beurré, alternez béchamel, lasagnes, sauce à la viande et emmental. Terminez par la béchamel et le parmesan.", "Enfournez environ 45 min. Si le dessus gratine trop vite, couvrez de papier d''aluminium."], "sub": "à la béchamel muscadée", "title": "Lasagnes bolognaise"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/lasagnes-butternut', '{"alt": "Plat de lasagnes gratinées à la béchamel aux épinards", "cat": "Plats", "groups": [{"g": "Lasagnes", "ing": [{"items": [{"c": "Épicerie", "n": "Lasagnes", "q": 10, "u": "feuilles"}], "t": "10 feuilles de lasagnes environ"}, {"items": [{"c": "Crèmerie & fromages", "n": "Pecorino râpé", "q": 100, "u": "g"}], "t": "100 g de pecorino râpé"}, {"items": [{"c": "Placard", "n": "Sel", "q": null, "u": ""}, {"c": "Placard", "n": "Poivre", "q": null, "u": ""}], "t": "Sel et poivre"}]}, {"g": "Purée de butternut", "ing": [{"items": [{"c": "Fruits & légumes", "n": "Courge butternut", "q": 1, "u": ""}], "t": "1 courge butternut (800 g environ)"}, {"items": [{"c": "Crèmerie & fromages", "n": "Chèvre frais", "q": 150, "u": "g"}], "t": "150 g de chèvre frais"}, {"items": [{"c": "Crèmerie & fromages", "n": "Picodon", "q": 1, "u": ""}], "t": "1 picodon"}, {"items": [{"c": "Fruits & légumes", "n": "Oignon", "q": 1, "u": ""}], "t": "1 petit oignon"}, {"items": [{"c": "Épicerie", "n": "Bouillon de légumes", "q": 20, "u": "cl"}], "t": "20 cl de bouillon de légumes"}, {"items": [{"c": "Placard", "n": "Huile d''olive", "q": null, "u": ""}], "t": "Huile d''olive"}]}, {"g": "Béchamel aux épinards", "ing": [{"items": [{"c": "Fruits & légumes", "n": "Pousses d''épinards", "q": 120, "u": "g"}], "t": "120 g de pousses d''épinards"}, {"items": [{"c": "Crèmerie & fromages", "n": "Beurre", "q": 60, "u": "g"}], "t": "60 g de beurre doux"}, {"items": [{"c": "Placard", "n": "Farine", "q": 30, "u": "g"}], "t": "30 g de farine"}, {"items": [{"c": "Crèmerie & fromages", "n": "Picodon", "q": 1, "u": ""}], "t": "1 picodon"}, {"items": [{"c": "Fruits & légumes", "n": "Ail", "q": 2, "u": "gousses"}], "t": "2 gousses d''ail pressées"}, {"items": [{"c": "Crèmerie & fromages", "n": "Lait", "q": 0.5, "u": "l"}], "t": "½ l de lait"}, {"items": [{"c": "Épicerie", "n": "Bouillon de légumes", "q": 0.25, "u": "l"}], "t": "¼ l de bouillon de légumes"}, {"items": [{"c": "Épicerie", "n": "Noix de muscade", "q": 0.25, "u": "c. à café"}], "t": "¼ c. à café de noix de muscade"}, {"items": [{"c": "Fruits & légumes", "n": "Sauge", "q": 5, "u": "feuilles"}], "t": "5 feuilles de sauge séchée"}, {"items": [{"c": "Fruits & légumes", "n": "Romarin", "q": 1, "u": "brin"}], "t": "1 brin de romarin"}]}], "img": "/photos/lasagnes-butternut.jpg", "meta": [["Préparation", "1 h"], ["Cuisson", "40 min"], ["Portions", "4 personnes"]], "notes": ["Matériel : un plat allant au four, une casserole et un plat à gratin d''environ 20 cm.", "Notes : le picodon est un chèvre sec de Drôme-Ardèche. À défaut, prenez une bûche de chèvre coupée en deux, une moitié pour la purée, l''autre pour la béchamel."], "portions": 4, "ptxt": "4 personnes", "source": "D''après Tangerine Zest", "steps": ["Préchauffez le four à 190 °C. Mélangez la butternut pelée et coupée en dés avec l''huile d''olive, salez, poivrez et enfournez 25 à 30 min, en remuant de temps en temps.", "Pendant ce temps, faites revenir l''oignon émincé dans un filet d''huile d''olive.", "Écrasez la courge en purée et ajoutez le bouillon en mélangeant. Incorporez le chèvre frais, un picodon en petits morceaux et l''oignon. Salez, poivrez.", "Béchamel : faites fondre le beurre avec l''ail, la sauge et le romarin 2 à 3 min, jusqu''à ce qu''il blondisse. Retirez les herbes, ajoutez la farine tamisée, puis le lait et le bouillon tièdes petit à petit en fouettant. Ajoutez la muscade, salez, poivrez.", "À feu doux, faites fondre le second picodon dans la sauce, puis ajoutez les épinards et mélangez rapidement. Retirez du feu.", "Dans le plat beurré, alternez béchamel, purée et lasagnes, 4 fois. Finissez par la béchamel et le pecorino. Enfournez 40 min à 190 °C, jusqu''à ce que le dessus soit doré.", "Laissez reposer 5 min et servez avec une salade verte."], "sub": "butternut, chèvre et épinards", "title": "Lasagnes végétariennes butternut, chèvre et épinards"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/osso-bucco', '{"alt": "Osso bucco à la sauce tomate dans une poêle en fonte", "cat": "Plats", "groups": [{"g": "", "ing": [{"items": [{"c": "Viandes & poissons", "n": "Osso bucco", "q": 1.5, "u": "kg"}], "t": "1,5 kg d''osso bucco (jarret de veau en tranches)"}, {"items": [{"c": "Fruits & légumes", "n": "Tomates", "q": 5, "u": ""}], "t": "5 tomates"}, {"items": [{"c": "Fruits & légumes", "n": "Champignons de Paris", "q": 200, "u": "g"}], "t": "200 g de champignons de Paris"}, {"items": [{"c": "Fruits & légumes", "n": "Oignon", "q": 1, "u": ""}], "t": "1 oignon"}, {"items": [{"c": "Épicerie", "n": "Concentré de tomate", "q": 1, "u": ""}], "t": "1 petite boîte de concentré de tomate"}, {"items": [{"c": "Épicerie", "n": "Olives vertes", "q": 1, "u": "boîte"}], "t": "1 boîte d''olives vertes"}, {"items": [{"c": "Épicerie", "n": "Olives noires", "q": 1, "u": "boîte"}], "t": "1 boîte d''olives noires"}, {"items": [{"c": "Épicerie", "n": "Vin blanc", "q": 0.5, "u": "verre"}], "t": "½ verre de vin blanc"}, {"items": [{"c": "Placard", "n": "Farine", "q": null, "u": ""}], "t": "Un peu de farine"}, {"items": [{"c": "Crèmerie & fromages", "n": "Beurre", "q": 1, "u": "noix"}], "t": "1 noix de beurre"}, {"items": [{"c": "Placard", "n": "Huile d''olive", "q": null, "u": ""}], "t": "Huile d''olive"}, {"items": [{"c": "Fruits & légumes", "n": "Laurier", "q": 1, "u": "feuille"}], "t": "1 feuille de laurier"}, {"items": [{"c": "Placard", "n": "Sel", "q": null, "u": ""}, {"c": "Placard", "n": "Poivre", "q": null, "u": ""}], "t": "Sel et poivre"}]}], "img": "/photos/osso-bucco.jpg", "meta": [["Préparation", "45 min"], ["Cuisson", "1 h"], ["Portions", "6 personnes"]], "notes": ["Matériel : un faitout avec couvercle et deux casseroles.", "Notes : encore meilleur réchauffé, vous pouvez le préparer la veille. Variante des lecteurs : un peu de céleri et de carotte en début de cuisson, et le zeste d''une demi- orange à la fin."], "portions": 6, "ptxt": "6 personnes", "source": "D''après Vincent Berthet (Journal des Femmes)", "steps": ["Plongez les tomates 1 min dans l''eau bouillante, l''une après l''autre, puis pelez-les et coupez-les en quatre.", "Nettoyez les champignons, coupez-les en 2 ou en 4 selon leur taille et faites-les cuire 10 min à l''eau bouillante. Égouttez et réservez.", "Dans un faitout, faites chauffer l''huile d''olive et le beurre. Farinez les morceaux d''osso bucco et faites-les dorer des deux côtés. Salez, poivrez, puis retirez-les et réservez.", "Dans le même faitout, faites dorer l''oignon coupé en petits morceaux. Ajoutez les tomates et laissez-les fondre à couvert. Ajoutez le concentré s''il manque du jus, et un peu d''eau si l''oignon accroche.", "Retirez le couvercle, versez le vin blanc, salez, poivrez, puis ajoutez le laurier, les olives vertes et noires et les champignons.", "Remettez la viande, couvrez et laissez cuire 1 h à feu moyen."], "sub": "traditionnel à l''italienne", "title": "Osso bucco à l''italienne"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/overnight-porridge', '{"alt": "Pot d’overnight porridge garni de myrtilles, beurre de cacahuète et noix de pécan", "cat": "Petit-déj & goûter", "groups": [{"g": "", "ing": [{"items": [{"c": "Épicerie", "n": "Flocons d''avoine", "q": 60, "u": "g"}], "t": "60 g de flocons d''avoine"}, {"items": [{"c": "Crèmerie & fromages", "n": "Lait", "q": 25, "u": "cl"}], "t": "25 cl de lait de votre choix (animal ou végétal)"}, {"items": [{"c": "Épicerie", "n": "Sirop d''érable", "q": 2, "u": "c. à soupe"}], "t": "1 à 2 c. à soupe de sirop d''érable, d''agave ou de miel"}, {"items": [{"c": "Épicerie", "n": "Graines de chia", "q": 2, "u": "c. à soupe"}], "t": "2 c. à soupe de graines de chia (facultatif)"}, {"items": [{"c": "Épicerie", "n": "Cacao amer", "q": 1, "u": "c. à soupe"}], "t": "1 c. à soupe de cacao amer (facultatif)"}]}, {"g": "Pour le topping", "ing": [{"items": [{"c": "Épicerie", "n": "Purée d''oléagineux", "q": null, "u": ""}], "t": "Purée d''oléagineux (cacahuète, amande...)"}, {"items": [{"c": "Fruits & légumes", "n": "Fruits frais", "q": null, "u": ""}], "t": "Fruits frais de saison"}, {"items": [{"c": "Épicerie", "n": "Noix", "q": null, "u": ""}], "t": "Noix, amandes, noisettes ..."}, {"items": [{"c": "Épicerie", "n": "Graines", "q": null, "u": ""}], "t": "Graines (tournesol, lin, courge...)"}]}], "img": "/photos/overnight-porridge.jpg", "meta": [["Préparation", "5 min"], ["Repos au frais", "1 nuit (10 h)"], ["Portions", "2 personnes"]], "notes": ["Matériel : un récipient ou 2 pots avec couvercle.", "Notes : pas de trempage à prévoir en plus, c''est la nuit au réfrigérateur qui fait gonfler les flocons d''avoine et les graines de chia. Pensez simplement à le préparer la veille au soir."], "portions": 2, "ptxt": "2 personnes", "source": "D''après Tangerine Zest", "steps": ["La veille, versez dans un récipient ou dans 2 pots les flocons d''avoine, le lait, le sirop d''érable et, si vous en mettez, les graines de chia et le cacao. Mélangez bien.", "Couvrez et placez au réfrigérateur pour la nuit.", "Le lendemain, garnissez selon vos envies : purée d''oléagineux, fruits frais, noix ou graines. Dégustez aussitôt, bien frais.", "Une base à varier à l''infini : banane, myrtilles, pépites de chocolat, cranberries, granola maison..."], "sub": "", "title": "Overnight porridge"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/pancakes', '{"alt": "Pile de pancakes nappés de sirop d’érable", "cat": "Petit-déj & goûter", "groups": [{"g": "", "ing": [{"items": [{"c": "Placard", "n": "Farine", "q": 125, "u": "g"}], "t": "125 g de farine"}, {"items": [{"c": "Crèmerie & fromages", "n": "Œufs", "q": 2, "u": ""}], "t": "2 œufs"}, {"items": [{"c": "Épicerie", "n": "Sucre vanillé", "q": 1, "u": "sachet"}], "t": "1 sachet de sucre vanillé (ou 1 c. à café d''extrait de vanille)"}, {"items": [{"c": "Crèmerie & fromages", "n": "Lait", "q": 150, "u": "ml"}], "t": "150 ml de lait demi-écrémé"}, {"items": [{"c": "Placard", "n": "Sucre", "q": 2, "u": "c. à soupe"}], "t": "2 c. à soupe de sucre"}, {"items": [{"c": "Épicerie", "n": "Levure chimique", "q": 1, "u": "c. à café"}], "t": "1 c. à café de levure chimique (ou de bicarbonate)"}, {"items": [{"c": "Crèmerie & fromages", "n": "Beurre", "q": null, "u": ""}], "t": "Beurre ou huile pour la cuisson"}, {"items": [{"c": "Placard", "n": "Sel", "q": 1, "u": "pincée"}], "t": "1 pincée de sel"}]}], "img": "/photos/pancakes.jpg", "meta": [["Préparation", "5 min"], ["Cuisson", "10 min"], ["Portions", "4 personnes"]], "notes": ["Matériel : deux bols, un fouet ou un batteur et une petite poêle.", "Notes : laissez reposer la pâte 15 à 30 min avant d''ajouter les blancs en neige. Ce sont les blancs montés qui rendent les pancakes ultra moelleux."], "portions": 4, "ptxt": "4 personnes", "source": "D''après Hervé Cuisine", "steps": ["Dans un grand bol, mélangez les ingrédients secs : farine, levure, sucre, sucre vanillé et la pincée de sel.", "Séparez les blancs des jaunes d''œufs. Dans un autre bol, mélangez les jaunes avec le lait, puis versez sur les ingrédients secs en mélangeant : la pâte doit être bien épaisse.", "Laissez reposer 15 à 30 min.", "Battez les blancs d''œufs en neige et incorporez-les délicatement à la pâte.", "Faites chauffer une petite poêle avec un peu de beurre ou d''huile. Versez une petite louche de pâte et laissez cuire environ 1 min : quand le bord est doré et que des petites bulles se forment sur le dessus, retournez le pancake et laissez cuire 1 min de l''autre côté."], "sub": "", "title": "Pancakes moelleux"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/pao-de-queijo', '{"alt": "Pyramide de petits pains au fromage brésiliens dans un plat", "cat": "Soupes & entrées", "groups": [{"g": "", "ing": [{"items": [{"c": "Épicerie", "n": "Farine de tapioca", "q": 500, "u": "g"}], "t": "500 g de farine de tapioca"}, {"items": [{"c": "Crèmerie & fromages", "n": "Parmesan", "q": 200, "u": "g"}], "t": "200 g de parmesan frais râpé"}, {"items": [{"c": "Crèmerie & fromages", "n": "Gruyère", "q": 200, "u": "g"}], "t": "200 g de gruyère râpé puis haché"}, {"items": [{"c": "Crèmerie & fromages", "n": "Œufs", "q": 220, "u": "g"}], "t": "220 g d''œufs (environ 4)"}, {"items": [{"c": "Crèmerie & fromages", "n": "Lait", "q": 200, "u": "ml"}], "t": "200 ml de lait"}, {"items": [{"c": "Placard", "n": "Huile", "q": 75, "u": "ml"}], "t": "75 ml d''huile"}, {"items": [{"c": "Placard", "n": "Sel", "q": 2, "u": "c. à café"}], "t": "2 c. à café de sel"}]}], "img": "/photos/pao-de-queijo.jpg", "meta": [["Préparation", "20 min"], ["Cuisson", "15 à 20 min"], ["Portions", "15 personnes"]], "notes": ["Matériel : une casserole, une terrine et une plaque à pâtisserie.", "Notes : la farine de tapioca (rayon asiatique) est la même chose que le polvilho doce brésilien. À déguster dès la sortie du four, croustillants dessus et moelleux à cœur, éventuellement avec une noix de beurre salé au milieu. Laissés une nuit au frais avant cuisson, ils ont une croûte plus épaisse."], "portions": 15, "ptxt": "15 personnes", "source": "D''après Bernard Laurance (La cuisine de Bernard)", "steps": ["Dans une casserole, portez le lait et l''huile à ébullition, puis retirez du feu.", "Pendant ce temps, mélangez la farine de tapioca et le sel dans une terrine. Versez dessus le mélange très chaud et mélangez vigoureusement.", "Ajoutez tout le fromage (parmesan et gruyère), mélangez, puis ajoutez les œufs. Mélangez de nouveau, c''est plus facile à la main (ou au robot).", "La pâte est collante, c''est normal. Si elle colle trop pour former des boulettes, placez-la 30 min au frais.", "Préchauffez le four à 180 °C. Formez des boulettes de la taille d''une noix et posez-les sur la plaque (elles gonflent peu, vous pouvez les rapprocher).", "Enfournez 15 à 20 min : les petits pains doivent être bien ronds et légèrement dorés."], "sub": "les petits pains au fromage brésiliens", "title": "Pão de queijo"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/parmentier-vegetarien', '{"alt": "Parmentier végétarien gratiné dans un plat en verre", "cat": "Plats", "groups": [{"g": "", "ing": [{"items": [{"c": "Fruits & légumes", "n": "Pommes de terre", "q": 800, "u": "g"}], "t": "800 g de pommes de terre"}, {"items": [{"c": "Épicerie", "n": "Lentilles vertes", "q": 150, "u": "g"}], "t": "150 g de lentilles vertes sèches (ou 400 g cuites et égouttées)"}, {"items": [{"c": "Fruits & légumes", "n": "Champignons de Paris", "q": 200, "u": "g"}], "t": "200 g de champignons de Paris"}, {"items": [{"c": "Fruits & légumes", "n": "Carottes", "q": 2, "u": ""}], "t": "2 carottes"}, {"items": [{"c": "Fruits & légumes", "n": "Oignon", "q": 1, "u": ""}], "t": "1 oignon"}, {"items": [{"c": "Fruits & légumes", "n": "Ail", "q": 4, "u": "gousses"}], "t": "4 gousses d''ail"}, {"items": [{"c": "Crèmerie & fromages", "n": "Lait", "q": 20, "u": "cl"}], "t": "20 cl de lait (ou lait végétal non sucré)"}, {"items": [{"c": "Placard", "n": "Huile d''olive", "q": 1, "u": "c. à soupe"}], "t": "1 c. à soupe d''huile d''olive"}, {"items": [{"c": "Épicerie", "n": "Muscade", "q": 0.5, "u": "c. à café"}], "t": "½ c. à café de muscade moulue"}, {"items": [{"c": "Placard", "n": "Sel", "q": null, "u": ""}, {"c": "Placard", "n": "Poivre", "q": null, "u": ""}], "t": "Sel et poivre"}, {"items": [{"c": "Crèmerie & fromages", "n": "Beurre", "q": null, "u": ""}], "t": "Facultatif : un peu de beurre ou d''huile d''olive dans la purée"}, {"items": [{"c": "Épicerie", "n": "Chapelure", "q": null, "u": ""}], "t": "Facultatif : chapelure ou polenta pour gratiner"}]}], "img": "/photos/parmentier-vegetarien.jpg", "meta": [["Préparation", "20 min"], ["Cuisson", "50 min"], ["Portions", "4 personnes"]], "notes": ["Matériel : un cuit-vapeur, une poêle avec couvercle, un mixeur plongeant et un plat à four (ou 4 plats individuels).", "Notes : pas de trempage pour les lentilles vertes : rincez-les simplement avant de les cuire 20 min dans l''eau bouillante non salée."], "portions": 4, "ptxt": "4 personnes", "source": "D''après Stéphanie, La cerise sur le maillot", "steps": ["Épluchez les pommes de terre et faites-les cuire environ 20 min à la vapeur. En même temps, faites cuire les lentilles sèches 20 min dans l''eau bouillante non salée, puis égouttez-les.", "Épluchez les carottes et taillez-les en dés. Émincez l''ail et l''oignon. Nettoyez les champignons et coupez-les en morceaux.", "Dans une poêle, faites revenir l''oignon et les carottes 2 min à feu vif dans l''huile d''olive. Ajoutez les champignons, salez, poivrez, couvrez et laissez cuire 5 min à feu moyen-vif.", "Ajoutez l''ail et poursuivez 2 min à couvert, à feu moyen.", "Mélangez avec les lentilles et mixez grossièrement. Rectifiez l''assaisonnement et étalez dans le plat.", "Préchauffez le four à 180 °C (chaleur tournante). Écrasez les pommes de terre, incorporez le lait et la muscade, salez et mélangez.", "Répartissez la purée sur les lentilles et tracez des lignes à la fourchette. Pour un dessus plus croustillant, parsemez d''un peu de chapelure ou de polenta. Enfournez 20 min à mi-hauteur, puis éventuellement 2 min sous le gril."], "sub": "aux lentilles et champignons", "title": "Parmentier végétarien aux lentilles et champignons"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/patates-douces-farcies', '{"alt": "Patates douces farcies au chou frisé et à la feta sur une planche", "cat": "Plats", "groups": [{"g": "", "ing": [{"items": [{"c": "Fruits & légumes", "n": "Patates douces", "q": 4, "u": ""}], "t": "4 patates douces moyennes"}, {"items": [{"c": "Fruits & légumes", "n": "Chou frisé", "q": 200, "u": "g"}], "t": "200 g de chou frisé frais"}, {"items": [{"c": "Crèmerie & fromages", "n": "Feta", "q": 150, "u": "g"}], "t": "150 g de feta"}, {"items": [{"c": "Fruits & légumes", "n": "Ail", "q": 2, "u": "gousses"}], "t": "2 gousses d''ail"}, {"items": [{"c": "Placard", "n": "Huile d''olive", "q": 2, "u": "c. à soupe"}], "t": "2 c. à soupe d''huile d''olive"}, {"items": [{"c": "Épicerie", "n": "Paprika doux", "q": 1, "u": "c. à café"}], "t": "1 c. à café de paprika doux"}, {"items": [{"c": "Placard", "n": "Sel", "q": null, "u": ""}, {"c": "Placard", "n": "Poivre", "q": null, "u": ""}], "t": "Sel et poivre"}, {"items": [{"c": "Fruits & légumes", "n": "Graines de courge", "q": null, "u": ""}], "t": "Graines de courge (facultatif)"}]}], "img": "/photos/patates-douces-farcies.jpg", "meta": [["Préparation", "15 min"], ["Cuisson", "45 min"], ["Portions", "4 personnes"]], "notes": ["Matériel : une plaque allant au four et une poêle.", "Notes : le temps de cuisson dépend de la taille des patates douces. Elles sont prêtes quand la pointe d''un couteau s''enfonce sans résistance."], "portions": 4, "ptxt": "4 personnes", "source": "D''après Cuisine et Vins de France", "steps": ["Préchauffez le four à 200 °C. Lavez les patates douces, piquez-les à plusieurs endroits avec une fourchette et posez-les sur une plaque légèrement huilée.", "Enfournez environ 45 min, jusqu''à ce qu''elles soient tendres à cœur.", "Pendant ce temps, hachez l''ail et le chou frisé. Dans une poêle, faites chauffer l''huile d''olive à feu moyen et faites revenir l''ail quelques instants.", "Ajoutez le chou frisé et faites-le sauter quelques minutes jusqu''à ce qu''il ramollisse. Assaisonnez de sel, de poivre et de paprika, puis retirez du feu.", "Fendez les patates douces dans la longueur sans les séparer et écrasez légèrement la chair à la fourchette. Garnissez de chou frisé et parsemez de feta émiettée.", "Remettez quelques minutes au four, le temps que la feta commence à fondre. Servez chaud, parsemé de graines de courge pour le croquant."], "sub": "à la feta et au chou frisé", "title": "Patates douces farcies à la feta et au chou frisé"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/pate-brisee', '{"alt": "Pâte brisée étalée et enroulée autour d’un rouleau à pâtisserie", "cat": "Bases", "groups": [{"g": "", "ing": [{"items": [{"c": "Placard", "n": "Farine", "q": 180, "u": "g"}], "t": "180 g de farine T45"}, {"items": [{"c": "Crèmerie & fromages", "n": "Beurre", "q": 90, "u": "g"}], "t": "90 g de beurre"}, {"items": [{"c": "Placard", "n": "Eau", "q": 30, "u": "ml"}], "t": "30 ml d''eau glacée"}, {"items": [{"c": "Placard", "n": "Sel", "q": 1, "u": "pincée"}], "t": "1 pincée de sel"}]}], "img": "/photos/pate-brisee.jpg", "meta": [["Préparation", "10 min"], ["Repos", "30 min minimum"], ["Portions", "1 pâte (24-26 cm)"]], "notes": ["Matériel : un robot (ou un saladier), du film alimentaire et un rouleau à pâtisserie.", "Version sucrée : ajoutez environ 25 g de sucre, et éventuellement de la vanille, de la cannelle ou des zestes d''agrumes.", "Notes : pour une tarte salée, parfumez la pâte avec du thym, du romarin, du piment d''Espelette ou un peu de parmesan ou de comté râpé. Bien emballée, elle se conserve 2 à 3 jours au réfrigérateur, et se congèle crue (décongélation lente au réfrigérateur)."], "portions": 1, "ptxt": "1 pâte (24-26 cm)", "source": "D''après Anne, Papilles & Pupilles", "steps": ["Une heure avant, sortez le beurre du réfrigérateur, coupez-le en dés et laissez-le ramollir à température ambiante.", "Quand il est souple, mettez le beurre dans le bol du robot avec la farine et le sel. Mélangez jusqu''à obtenir une texture sableuse et friable.", "Ajoutez l''eau glacée et mélangez juste assez pour que la pâte s''amalgame, sans trop la travailler.", "Formez une boule, enveloppez-la de film alimentaire et laissez-la reposer au moins 30 min au réfrigérateur. Ce repos évite qu''elle ne se rétracte à la cuisson.", "Sortez-la quelques minutes avant de l''utiliser. Farinez légèrement le plan de travail et étalez-la au rouleau.", "Selon la recette, faites-la cuire à blanc avant de la garnir, ou directement avec sa garniture en suivant le temps et la température de la tarte."], "sub": "maison, pour tartes salées ou sucrées", "title": "Pâte brisée maison"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/pot-au-feu', '{"alt": "Faitout de pot-au-feu avec viande, carottes et bouillon", "cat": "Plats", "groups": [{"g": "", "ing": [{"items": [{"c": "Viandes & poissons", "n": "Paleron", "q": 400, "u": "g"}], "t": "400 g de paleron"}, {"items": [{"c": "Viandes & poissons", "n": "Gîte", "q": 400, "u": "g"}], "t": "400 g de gîte"}, {"items": [{"c": "Viandes & poissons", "n": "Plat de côte", "q": 400, "u": "g"}], "t": "400 g de plat de côte"}, {"items": [{"c": "Viandes & poissons", "n": "Queue de bœuf", "q": 1, "u": ""}], "t": "1 queue de bœuf"}, {"items": [{"c": "Viandes & poissons", "n": "Os à moelle", "q": 4, "u": ""}], "t": "4 os à moelle"}, {"items": [{"c": "Fruits & légumes", "n": "Carottes", "q": 8, "u": ""}], "t": "8 carottes"}, {"items": [{"c": "Fruits & légumes", "n": "Navets", "q": 4, "u": ""}], "t": "4 navets"}, {"items": [{"c": "Fruits & légumes", "n": "Poireaux", "q": 5, "u": ""}], "t": "5 poireaux"}, {"items": [{"c": "Fruits & légumes", "n": "Céleri", "q": 1, "u": "branche"}], "t": "1 branche de céleri"}, {"items": [{"c": "Fruits & légumes", "n": "Oignon", "q": 1, "u": ""}], "t": "1 oignon"}, {"items": [{"c": "Fruits & légumes", "n": "Ail", "q": 2, "u": "gousses"}], "t": "2 gousses d''ail"}, {"items": [{"c": "Placard", "n": "Eau", "q": null, "u": ""}], "t": "Eau froide (pour couvrir)"}, {"items": [{"c": "Placard", "n": "Gros sel", "q": 1, "u": "c. à soupe"}], "t": "1 c. à soupe de gros sel"}, {"items": [{"c": "Épicerie", "n": "Clous de girofle", "q": 4, "u": ""}], "t": "4 clous de girofle"}, {"items": [{"c": "Placard", "n": "Poivre", "q": 15, "u": ""}], "t": "15 grains de poivre"}, {"items": [{"c": "Fruits & légumes", "n": "Bouquet garni", "q": 1, "u": ""}], "t": "1 bouquet garni"}]}], "img": "/photos/pot-au-feu.jpg", "meta": [["Préparation", "15 min"], ["Cuisson", "3 h"], ["Portions", "4 personnes"]], "notes": ["Matériel : un grand faitout ou une grande cocotte et une écumoire.", "Notes : servez avec de la moutarde, des cornichons et du gros sel. Gardez le bouillon : filtré et dégraissé, il fait une excellente base de soupe et se congèle très bien."], "portions": 4, "ptxt": "4 personnes", "source": "", "steps": ["Épluchez et coupez les carottes, les navets, les poireaux et le céleri en gros tronçons.", "Coupez l''oignon en quatre et piquez chaque quartier d''un clou de girofle. Gardez les gousses d''ail en chemise.", "Salez les extrémités des os à moelle pour éviter que la moelle ne s''échappe pendant la cuisson.", "Dans un grand faitout, placez les viandes (paleron, gîte, plat de côte, queue de bœuf), les os à moelle et tous les légumes.", "Ajoutez les grains de poivre, le bouquet garni et le gros sel, puis couvrez d''eau froide.", "Portez à ébullition, puis laissez cuire 3 h à petits frémissements, en écumant régulièrement.", "Servez les viandes, les os à moelle et les légumes, accompagnés d''un peu de bouillon."], "sub": "traditionnel", "title": "Pot-au-feu"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/puree-maison', '{"alt": "Bol de purée de pommes de terre maison, avec des pommes de terre", "cat": "Bases", "groups": [{"g": "", "ing": [{"items": [{"c": "Fruits & légumes", "n": "Pommes de terre", "q": 1, "u": "kg"}], "t": "1 kg de pommes de terre à chair farineuse"}, {"items": [{"c": "Crèmerie & fromages", "n": "Beurre", "q": 150, "u": "g"}], "t": "150 g de beurre bien froid"}, {"items": [{"c": "Crèmerie & fromages", "n": "Lait entier", "q": 200, "u": "g"}], "t": "200 g de lait entier"}, {"items": [{"c": "Épicerie", "n": "Noix de muscade", "q": null, "u": ""}], "t": "Noix de muscade"}, {"items": [{"c": "Placard", "n": "Gros sel", "q": null, "u": ""}], "t": "Gros sel pour l''eau de cuisson"}, {"items": [{"c": "Placard", "n": "Sel", "q": null, "u": ""}], "t": "Sel fin et poivre blanc"}]}], "img": "/photos/puree-maison.jpg", "meta": [["Préparation", "10 min"], ["Cuisson", "20 min"], ["Portions", "4 personnes"]], "notes": ["Matériel : une marmite et un presse-purée.", "Accord vin : un vin blanc de type condrieu.", "Notes : n''utilisez pas de mixeur, il rend la purée collante et élastique. Ne laissez pas les pommes de terre trop longtemps dans l''eau. Trop épaisse : ajoutez un peu de lait chaud. Trop liquide : ajoutez une pomme de terre cuite écrasée."], "portions": 4, "ptxt": "4 personnes", "source": "D''après 750g", "steps": ["Lavez, épluchez et coupez les pommes de terre en morceaux d''environ 5 cm.", "Mettez-les dans une marmite, couvrez-les largement d''eau froide salée au gros sel et faites-les cuire à petite ébullition jusqu''à ce qu''elles soient bien cuites.", "Pendant ce temps, coupez le beurre en dés de 1 cm et réservez-le au frais. Faites chauffer le lait sans le faire bouillir.", "Égouttez les pommes de terre et passez-les au presse-purée, encore chaudes, directement dans la marmite.", "Sur feu doux, ajoutez le beurre froid en mélangeant vigoureusement, puis le lait petit à petit jusqu''à obtenir la consistance voulue.", "Rectifiez l''assaisonnement avec du sel, du poivre blanc et un peu de muscade râpée."], "sub": "de pommes de terre, onctueuse", "title": "Purée maison"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/quiche-brocolis-champignons', '{"alt": "Quiche aux brocolis et champignons dans un moule", "cat": "Plats", "groups": [{"g": "Pâte brisée", "ing": [{"items": [{"c": "Placard", "n": "Farine", "q": 180, "u": "g"}], "t": "180 g de farine"}, {"items": [{"c": "Crèmerie & fromages", "n": "Beurre", "q": 75, "u": "g"}], "t": "75 g de beurre mou"}, {"items": [{"c": "Placard", "n": "Eau", "q": 0.5, "u": "verre"}], "t": "½ verre d''eau"}, {"items": [{"c": "Placard", "n": "Sel", "q": 1, "u": "pincée"}], "t": "1 pincée de sel"}]}, {"g": "Garniture", "ing": [{"items": [{"c": "Fruits & légumes", "n": "Brocoli", "q": 2, "u": ""}], "t": "2 têtes de brocoli"}, {"items": [{"c": "Fruits & légumes", "n": "Champignons de Paris", "q": 1, "u": "boîte"}], "t": "1 boîte de champignons de Paris"}, {"items": [{"c": "Crèmerie & fromages", "n": "Gruyère râpé", "q": 100, "u": "g"}], "t": "100 g de gruyère râpé"}, {"items": [{"c": "Crèmerie & fromages", "n": "Œufs", "q": 3, "u": ""}], "t": "3 œufs"}, {"items": [{"c": "Crèmerie & fromages", "n": "Lait", "q": 10, "u": "cl"}], "t": "10 cl de lait"}, {"items": [{"c": "Épicerie", "n": "Moutarde", "q": 2, "u": "c. à soupe"}], "t": "2 c. à soupe de moutarde"}, {"items": [{"c": "Crèmerie & fromages", "n": "Crème fraîche", "q": 1, "u": "c. à soupe"}], "t": "1 c. à soupe de crème fraîche 20 %"}, {"items": [{"c": "Placard", "n": "Sel", "q": null, "u": ""}, {"c": "Placard", "n": "Poivre", "q": null, "u": ""}], "t": "Sel et poivre"}]}], "img": "/photos/quiche-brocolis-champignons.jpg", "meta": [["Préparation", "30 min"], ["Cuisson", "45 min"], ["Portions", "6 personnes"]], "notes": ["Matériel : un moule à tarte et un rouleau à pâtisserie.", "Notes : servez avec une salade verte. Variante : une pâte feuilletée, des épinards et du chèvre à la place des brocolis et des champignons."], "portions": 6, "ptxt": "6 personnes", "source": "D''après Laurence Dumont (CuisineAZ)", "steps": ["Préparez la pâte : mélangez la farine et le sel, ajoutez le beurre mou puis l''eau petit à petit. Formez une boule, filmez-la et laissez-la reposer au réfrigérateur.", "Détaillez les brocolis en petits bouquets et faites-les cuire 15 min dans une casserole d''eau salée. Égouttez-les.", "Égouttez les champignons.", "Préchauffez le four à 180 °C. Beurrez et farinez le moule, puis étalez la pâte et foncez-le.", "Badigeonnez le fond de tarte de moutarde, puis répartissez les brocolis, les champignons et le gruyère râpé.", "Battez les œufs avec la crème fraîche et le lait, salez et poivrez.", "Versez cet appareil sur la garniture et enfournez pour 45 min."], "sub": "aux brocolis et champignons", "title": "Quiche végétarienne brocolis et champignons"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/quiche-lorraine', '{"alt": "Parts de quiche lorraine dorée aux lardons", "cat": "Plats", "groups": [{"g": "", "ing": [{"items": [{"c": "Crèmerie & fromages", "n": "Pâte brisée", "q": 1, "u": ""}], "t": "1 pâte brisée"}, {"items": [{"c": "Viandes & poissons", "n": "Lardons", "q": 200, "u": "g"}], "t": "200 g de lardons"}, {"items": [{"c": "Fruits & légumes", "n": "Oignon", "q": 0.5, "u": ""}], "t": "½ oignon"}, {"items": [{"c": "Crèmerie & fromages", "n": "Gruyère râpé", "q": 100, "u": "g"}], "t": "100 g de gruyère râpé"}, {"items": [{"c": "Crèmerie & fromages", "n": "Œufs", "q": 2, "u": ""}], "t": "2 œufs"}, {"items": [{"c": "Crèmerie & fromages", "n": "Crème fraîche", "q": 200, "u": "ml"}], "t": "200 ml de crème fraîche"}, {"items": [{"c": "Crèmerie & fromages", "n": "Beurre", "q": 1, "u": "c. à soupe"}], "t": "1 c. à soupe de beurre"}, {"items": [{"c": "Placard", "n": "Sel", "q": null, "u": ""}, {"c": "Placard", "n": "Poivre", "q": null, "u": ""}], "t": "Sel et poivre"}]}], "img": "/photos/quiche-lorraine.jpg", "meta": [["Préparation", "15 min"], ["Cuisson", "40 à 50 min"], ["Portions", "4 personnes"]], "notes": ["Matériel : un moule à tarte, une poêle et un saladier.", "Accord vin : un vin d''Alsace (riesling sec, sylvaner ou pinot blanc) ou un rouge léger.", "Notes : pour la pâte maison, voir la fiche « Pâte brisée ». Variante plus croustillante avec une pâte feuilletée. Pour la réchauffer : four à 200 °C 10 min, éteignez-le, puis enfournez la quiche 10 min. Évitez le micro-ondes."], "portions": 4, "ptxt": "4 personnes", "source": "D''après As Werty (Journal des Femmes)", "steps": ["Préchauffez le four à 200 °C. Déposez la pâte brisée dans le moule à tarte.", "Coupez les lardons et l''oignon en morceaux et faites-les cuire dans le beurre. Laissez refroidir.", "Dans un saladier, mélangez les œufs, la crème fraîche et le gruyère râpé. Salez et poivrez.", "Versez d''abord les lardons et l''oignon sur la pâte, puis l''appareil, tout doucement.", "Enfournez pour 40 à 50 min, selon votre four, jusqu''à ce que la quiche soit bien dorée."], "sub": "la recette traditionnelle", "title": "Quiche lorraine"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/quinoa-chou-fleur', '{"alt": "Salade de quinoa et chou-fleur aux châtaignes, amandes et noisettes dans un bol", "cat": "Salades", "groups": [{"g": "", "ing": [{"items": [{"c": "Fruits & légumes", "n": "Chou-fleur", "q": 250, "u": "g"}], "t": "250 g de chou-fleur"}, {"items": [{"c": "Épicerie", "n": "Quinoa", "q": 100, "u": "g"}], "t": "100 g de quinoa"}, {"items": [{"c": "Épicerie", "n": "Châtaignes", "q": null, "u": ""}], "t": "Une douzaine de châtaignes cuites sous vide"}, {"items": [{"c": "Épicerie", "n": "Amandes", "q": 60, "u": "g"}], "t": "60 g d''amandes effilées"}, {"items": [{"c": "Épicerie", "n": "Noisettes", "q": 60, "u": "g"}], "t": "60 g de noisettes entières"}, {"items": [{"c": "Épicerie", "n": "Raisins secs", "q": 50, "u": "g"}], "t": "50 g de raisins secs"}, {"items": [{"c": "Placard", "n": "Huile d''olive", "q": 3, "u": "c. à soupe"}], "t": "3 c. à soupe d''huile d''olive"}, {"items": [{"c": "Épicerie", "n": "Vinaigre de miel", "q": 1, "u": "c. à soupe"}], "t": "1 c. à soupe de vinaigre de miel"}, {"items": [{"c": "Épicerie", "n": "Moutarde blanche", "q": 1, "u": "c. à soupe"}], "t": "1 c. à soupe de moutarde blanche"}, {"items": [{"c": "Fruits & légumes", "n": "Persil plat", "q": 4, "u": "brins"}], "t": "4 brins de persil plat"}, {"items": [{"c": "Placard", "n": "Sel", "q": null, "u": ""}, {"c": "Placard", "n": "Poivre", "q": null, "u": ""}], "t": "Sel et poivre du moulin"}]}], "img": "/photos/quinoa-chou-fleur.jpg", "meta": [["Préparation", "20 min"], ["Cuisson", "15 min"], ["Portions", "4 personnes"]], "notes": ["Matériel : une mandoline, une casserole et une poêle.", "Accord vin : un entre-deux-mers.", "Notes : tranchez le chou-fleur et les châtaignes le plus finement possible, comme des truffes. Le chou-fleur reste cru, c''est ce qui fait le croquant de la salade."], "portions": 4, "ptxt": "4 personnes", "source": "D''après Sophie Menut-Yovanovitch (Cuisine et Vins de France)", "steps": ["Rincez le quinoa. Faites-le cuire 10 à 15 min dans 2 fois son volume d''eau bouillante salée, puis passez-le sous l''eau froide et égouttez-le.", "Lavez le chou-fleur et coupez-le très finement à la mandoline. Tranchez les châtaignes en fines lamelles, puis mélangez chou-fleur, quinoa et châtaignes.", "Faites griller les amandes et les noisettes 3 min dans une poêle à sec. Ciselez le persil. Faites gonfler les raisins secs 5 min dans un bol d''eau chaude et égouttez-les.", "Préparez la vinaigrette : mélangez le vinaigre avec la moutarde, puis l''huile d''olive. Salez et poivrez.", "Mélangez la salade avec les raisins secs et la vinaigrette. Parsemez d''amandes, de noisettes et de persil. Servez à température ambiante."], "sub": "aux amandes et noisettes grillées", "title": "Quinoa et chou-fleur aux amandes et noisettes grillées"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/salade-epeautre', '{"alt": "Salade tiède d’épeautre au potiron, châtaignes et noisettes dans un bol", "cat": "Salades", "groups": [{"g": "", "ing": [{"items": [{"c": "Épicerie", "n": "Petit épeautre", "q": 250, "u": "g"}], "t": "250 g de petit épeautre"}, {"items": [{"c": "Fruits & légumes", "n": "Potiron", "q": 300, "u": "g"}], "t": "300 g de chair de potiron"}, {"items": [{"c": "Épicerie", "n": "Châtaignes", "q": 250, "u": "g"}], "t": "250 g de châtaignes cuites"}, {"items": [{"c": "Épicerie", "n": "Noisettes", "q": 50, "u": "g"}], "t": "50 g de noisettes décortiquées"}, {"items": [{"c": "Fruits & légumes", "n": "Oignon", "q": 1, "u": ""}], "t": "1 oignon"}, {"items": [{"c": "Épicerie", "n": "Lait d''avoine", "q": 5, "u": "cl"}], "t": "5 cl de lait d''avoine"}, {"items": [{"c": "Placard", "n": "Huile d''olive", "q": 4, "u": "c. à soupe"}], "t": "4 c. à soupe d''huile d''olive"}, {"items": [{"c": "Fruits & légumes", "n": "Persil plat", "q": 3, "u": "brins"}], "t": "3 brins de persil plat"}, {"items": [{"c": "Placard", "n": "Sel", "q": null, "u": ""}, {"c": "Placard", "n": "Poivre", "q": null, "u": ""}], "t": "Sel et poivre"}]}], "img": "/photos/salade-epeautre.jpg", "meta": [["Préparation", "30 min"], ["Cuisson", "50 min"], ["Portions", "4 personnes"]], "notes": ["Matériel : un grand saladier, une casserole, une sauteuse et une poêle.", "Accord vin : un Ardèche IGP rouge.", "Notes : prévoyez 45 min de trempage pour le petit épeautre avant de commencer. Pendant ce temps, préparez le potiron et l''oignon."], "portions": 4, "ptxt": "4 personnes", "source": "D''après Sophie Menut (Cuisine et Vins de France)", "steps": ["Faites tremper le petit épeautre 45 min dans un grand saladier d''eau froide. Égouttez-le et faites-le cuire 30 min dans une grande casserole d''eau salée.", "Égouttez-le, remettez-le dans la casserole et versez le lait d''avoine. Mélangez et tenez au chaud. Émincez finement l''oignon et coupez le potiron en dés de 1 cm.", "Dans une sauteuse, faites chauffer la moitié de l''huile d''olive et laissez blondir l''oignon 2 min. Ajoutez le potiron et laissez-le suer 15 min à feu doux.", "Concassez les noisettes au couteau et faites-les dorer 3 min à sec dans une poêle. Émiettez grossièrement les châtaignes et ciselez le persil.", "Dans un saladier, mélangez délicatement l''épeautre, les châtaignes et les noisettes. Ajoutez le contenu de la sauteuse, le persil et le reste d''huile. Poivrez, mélangez et dégustez tiède."], "sub": "aux châtaignes et au potiron", "title": "Salade tiède d''épeautre aux châtaignes et au potiron"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/soupe-butternut-lentilles', '{"alt": "Bol de soupe de butternut au lait de coco, graines, paprika et sauge", "cat": "Soupes & entrées", "groups": [{"g": "", "ing": [{"items": [{"c": "Fruits & légumes", "n": "Courge butternut", "q": 800, "u": "g"}], "t": "800 g de courge butternut"}, {"items": [{"c": "Épicerie", "n": "Lentilles corail", "q": 200, "u": "g"}], "t": "200 g de lentilles corail"}, {"items": [{"c": "Fruits & légumes", "n": "Carottes", "q": 2, "u": ""}], "t": "2 petites carottes"}, {"items": [{"c": "Fruits & légumes", "n": "Oignon", "q": 1, "u": ""}], "t": "1 oignon"}, {"items": [{"c": "Fruits & légumes", "n": "Ail", "q": 1, "u": "gousse"}], "t": "1 gousse d''ail"}, {"items": [{"c": "Épicerie", "n": "Lait de coco", "q": 20, "u": "cl"}], "t": "20 cl de lait de coco"}, {"items": [{"c": "Placard", "n": "Eau", "q": 0.5, "u": "l"}], "t": "½ l d''eau environ"}, {"items": [{"c": "Épicerie", "n": "Curcuma", "q": 1, "u": "c. à café"}], "t": "1 c. à café de curcuma"}, {"items": [{"c": "Fruits & légumes", "n": "Gingembre", "q": 0.5, "u": "c. à café"}], "t": "½ c. à café de gingembre en poudre"}, {"items": [{"c": "Épicerie", "n": "Paprika fumé", "q": 0.5, "u": "c. à café"}], "t": "½ c. à café de paprika fumé"}, {"items": [{"c": "Placard", "n": "Huile d''olive", "q": null, "u": ""}], "t": "Huile d''olive"}, {"items": [{"c": "Placard", "n": "Sel", "q": null, "u": ""}, {"c": "Placard", "n": "Poivre", "q": null, "u": ""}], "t": "Sel et poivre"}, {"items": [{"c": "Fruits & légumes", "n": "Citron vert", "q": null, "u": ""}], "t": "Citron vert (facultatif)"}, {"items": [{"c": "Épicerie", "n": "Graines", "q": null, "u": ""}], "t": "Graines de courge, tournesol, lin (facultatif)"}]}], "img": "/photos/soupe-butternut-lentilles.jpg", "meta": [["Préparation", "15 min"], ["Cuisson", "25 min"], ["Portions", "6 personnes"]], "notes": ["Matériel : un faitout et un mixeur plongeant.", "Notes : pas de trempage pour les lentilles corail, rincez-les simplement à l''eau froide avant de les ajouter. Gardez un peu de lait de coco pour décorer les assiettes."], "portions": 6, "ptxt": "6 personnes", "source": "D''après Tangerine Zest", "steps": ["Épluchez l''oignon, l''ail et les carottes et coupez-les en morceaux. Dans un faitout, faites-les revenir à feu moyen avec un filet d''huile d''olive.", "Pendant ce temps, brossez la butternut sous l''eau, épluchez-la et coupez-la en petits dés. Ajoutez-la dans le faitout et remuez.", "Versez le lait de coco, le curcuma, le gingembre et le paprika, puis environ ½ l d''eau. Mélangez délicatement.", "À ébullition, ajoutez les lentilles corail et laissez cuire environ 15 min, jusqu''à ce que les légumes soient fondants.", "Retirez du feu et mixez. Salez, poivrez, ajoutez un peu de jus de citron vert et quelques graines. Dégustez chaud."], "sub": "aux lentilles corail et au lait de coco", "title": "Soupe de butternut aux lentilles corail et au lait de coco"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/soupe-champignons', '{"alt": "Gros plan sur une soupe crémeuse aux champignons, thym et poivre", "cat": "Soupes & entrées", "groups": [{"g": "", "ing": [{"items": [{"c": "Fruits & légumes", "n": "Champignons", "q": 500, "u": "g"}], "t": "500 g de champignons blonds ou de Paris"}, {"items": [{"c": "Fruits & légumes", "n": "Pomme de terre", "q": 1, "u": ""}], "t": "1 pomme de terre"}, {"items": [{"c": "Fruits & légumes", "n": "Poireau", "q": 1, "u": ""}], "t": "1 blanc de poireau en fines rondelles"}, {"items": [{"c": "Fruits & légumes", "n": "Échalotes", "q": 2, "u": ""}], "t": "2 échalotes finement ciselées"}, {"items": [{"c": "Fruits & légumes", "n": "Ail", "q": 1, "u": "gousse"}], "t": "1 gousse d''ail pressée"}, {"items": [{"c": "Épicerie", "n": "Vin blanc sec", "q": 5, "u": "cl"}], "t": "5 cl de vin blanc sec"}, {"items": [{"c": "Épicerie", "n": "Bouillon", "q": 0.5, "u": "l"}], "t": "½ l de bouillon de légumes ou de volaille"}, {"items": [{"c": "Crèmerie & fromages", "n": "Crème fraîche", "q": 10, "u": "cl"}], "t": "10 cl de crème fraîche liquide"}, {"items": [{"c": "Placard", "n": "Huile", "q": 1, "u": "c. à soupe"}], "t": "1 c. à soupe d''huile"}, {"items": [{"c": "Crèmerie & fromages", "n": "Beurre", "q": 1, "u": "c. à soupe"}], "t": "1 c. à soupe de beurre"}, {"items": [{"c": "Crèmerie & fromages", "n": "Pecorino", "q": 1, "u": "c. à soupe"}], "t": "1 c. à soupe de pecorino râpé"}, {"items": [{"c": "Fruits & légumes", "n": "Sauge", "q": 1, "u": "feuille"}], "t": "1 feuille de sauge"}, {"items": [{"c": "Épicerie", "n": "Noix de muscade", "q": 1, "u": "pincée"}], "t": "1 pincée de noix de muscade râpée"}, {"items": [{"c": "Placard", "n": "Poivre", "q": null, "u": ""}], "t": "Poivre du moulin"}, {"items": [{"c": "Fruits & légumes", "n": "Céleri", "q": 1, "u": ""}], "t": "1 petite branche de céleri (facultatif)"}]}, {"g": "Pour le topping", "ing": [{"items": [{"c": "Fruits & légumes", "n": "Champignons des bois", "q": null, "u": ""}], "t": "Champignons des bois poêlés"}, {"items": [{"c": "Épicerie", "n": "Croûtons", "q": null, "u": ""}], "t": "Croûtons maison"}, {"items": [{"c": "Fruits & légumes", "n": "Persil", "q": null, "u": ""}], "t": "Persil ciselé"}, {"items": [{"c": "Épicerie", "n": "Pignons de pin", "q": null, "u": ""}], "t": "Pignons de pin"}]}], "img": "/photos/soupe-champignons.jpg", "meta": [["Préparation", "10 min"], ["Cuisson", "20 min"], ["Portions", "4 personnes"]], "notes": ["Matériel : une cocotte et un mixeur plongeant."], "portions": 4, "ptxt": "4 personnes", "source": "D''après Tangerine Zest", "steps": ["Épluchez et lavez la pomme de terre, coupez-la en morceaux et faites-la cuire dans l''eau bouillante jusqu''à ce qu''elle soit tendre. Réservez.", "Lavez les champignons et coupez-les en petits morceaux. Faites-les dorer à la poêle avec le beurre, en remuant très peu pour qu''ils ne rendent pas trop d''eau.", "En même temps, dans une cocotte, faites chauffer l''huile à feu moyen avec l''ail, les échalotes et la muscade, jusqu''à ce que les échalotes soient translucides.", "Versez le vin blanc et portez à ébullition. Ajoutez le poireau, le céleri en petits morceaux, les champignons, le bouillon et la sauge. Couvrez et laissez mijoter 5 à 10 min à feu doux.", "Retirez la sauge, ajoutez la pomme de terre, la crème et le pecorino, mélangez, puis mixez le tout au mixeur plongeant.", "Servez bien chaud, poivrez à votre goût et ajoutez un peu de crème si besoin. Garnissez de champignons poêlés, de croûtons, de pignons de pin grillés et de persil."], "sub": "", "title": "Soupe crémeuse aux champignons"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/soupe-oignon', '{"alt": "Bol de soupe à l’oignon gratinée au fromage", "cat": "Soupes & entrées", "groups": [{"g": "", "ing": [{"items": [{"c": "Fruits & légumes", "n": "Oignons", "q": 4, "u": ""}], "t": "4 gros oignons"}, {"items": [{"c": "Crèmerie & fromages", "n": "Beurre", "q": 20, "u": "g"}], "t": "20 g de beurre"}, {"items": [{"c": "Crèmerie & fromages", "n": "Fromage râpé", "q": 100, "u": "g"}], "t": "100 g de fromage râpé"}, {"items": [{"c": "Épicerie", "n": "Pain de campagne", "q": 4, "u": "tranches"}], "t": "4 tranches de pain de campagne"}, {"items": [{"c": "Épicerie", "n": "Bouillon de volaille", "q": 1, "u": "l"}], "t": "1 l de bouillon de volaille"}, {"items": [{"c": "Placard", "n": "Farine", "q": 1, "u": "c. à soupe"}], "t": "1 c. à soupe de farine"}, {"items": [{"c": "Placard", "n": "Sel", "q": null, "u": ""}, {"c": "Placard", "n": "Poivre", "q": null, "u": ""}], "t": "Sel et poivre"}]}], "img": "/photos/soupe-oignon.jpg", "meta": [["Préparation", "10 min"], ["Cuisson", "40 min"], ["Portions", "4 personnes"]], "notes": ["Matériel : une casserole et 4 bols allant au four.", "Notes : prenez le temps de bien faire dorer les oignons : c''est leur caramélisation qui donne toute sa saveur à la soupe. Un gruyère ou un comté râpé gratine très bien."], "portions": 4, "ptxt": "4 personnes", "source": "", "steps": ["Épluchez et émincez finement les oignons.", "Dans une casserole, faites fondre le beurre et faites revenir les oignons à feu vif, en remuant, jusqu''à ce qu''ils deviennent translucides puis bien dorés.", "Saupoudrez de farine et mélangez 1 min.", "Salez, poivrez et versez le bouillon de volaille. Couvrez et laissez mijoter 30 min à feu doux.", "Allumez le gril du four. Répartissez la soupe dans 4 bols allant au four, posez une tranche de pain sur chacun et recouvrez de fromage râpé.", "Passez quelques minutes sous le gril, jusqu''à ce que le fromage soit gratiné, et servez aussitôt."], "sub": "gratinée au four", "title": "Soupe à l''oignon gratinée"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/taboule', '{"alt": "Saladier de taboulé à la semoule, tomates et menthe", "cat": "Salades", "groups": [{"g": "", "ing": [{"items": [{"c": "Épicerie", "n": "Semoule moyenne", "q": 250, "u": "g"}], "t": "200 à 250 g de semoule moyenne (ou boulgour)"}, {"items": [{"c": "Fruits & légumes", "n": "Tomates cœur de bœuf", "q": 500, "u": "g"}], "t": "400 à 500 g de tomates cœur de bœuf"}, {"items": [{"c": "Fruits & légumes", "n": "Concombre", "q": 1, "u": ""}], "t": "1 concombre"}, {"items": [{"c": "Fruits & légumes", "n": "Oignon nouveau", "q": 1, "u": ""}], "t": "1 oignon nouveau (ou ½ oignon rouge)"}, {"items": [{"c": "Fruits & légumes", "n": "Persil plat", "q": 2, "u": "c. à soupe"}], "t": "2 c. à soupe de persil plat ciselé"}, {"items": [{"c": "Fruits & légumes", "n": "Coriandre fraîche", "q": 2, "u": "c. à soupe"}], "t": "2 c. à soupe de coriandre fraîche ciselée"}, {"items": [{"c": "Placard", "n": "Huile d''olive", "q": 4, "u": "c. à soupe"}], "t": "2 à 4 c. à soupe d''huile d''olive"}, {"items": [{"c": "Fruits & légumes", "n": "Menthe fraîche", "q": 8, "u": "feuilles"}], "t": "8 feuilles de menthe fraîche, finement ciselées"}, {"items": [{"c": "Fruits & légumes", "n": "Citron bio", "q": 1, "u": ""}], "t": "1 citron bio (pour le jus)"}, {"items": [{"c": "Placard", "n": "Sel", "q": null, "u": ""}, {"c": "Placard", "n": "Poivre", "q": null, "u": ""}], "t": "Sel et poivre"}]}], "img": "/photos/taboule.jpg", "meta": [["Préparation", "15 min"], ["Repos au frais", "1 h minimum"], ["Portions", "4 personnes"]], "notes": ["Notes : c''est le jus des tomates qui fait gonfler la semoule, d''où l''importance de bien le garder. Avec du boulgour à la place de la semoule, laissez gonfler toute une nuit."], "portions": 4, "ptxt": "4 personnes", "source": "D''après Tangerine Zest", "steps": ["Dans un grand saladier, versez la semoule crue.", "Lavez, pelez et coupez les tomates en petits cubes (5 à 8 mm), en prenant soin de garder tout leur jus.", "Lavez et pelez le concombre, coupez-le lui aussi en petits dés, puis ajoutez tomates et concombre à la semoule.", "Émincez finement l''oignon. Lavez et ciselez la menthe, la coriandre et le persil plat, puis ajoutez le tout dans le saladier.", "Versez le jus d''un demi- citron et 2 cuillères à soupe d''huile d''olive. Salez, poivrez et mélangez bien.", "Couvrez et laissez reposer au réfrigérateur au moins 1 heure, voire toute une nuit.", "Au moment de servir, rectifiez l''assaisonnement avec un peu de citron, d''huile d''olive, de sel et de poivre si besoin. Remuez et servez bien frais."], "sub": "", "title": "Taboulé maison"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/tacos', '{"alt": "Tacos garnis de viande, tomates et coriandre sur une planche", "cat": "Plats", "groups": [{"g": "Tacos", "ing": [{"items": [{"c": "Viandes & poissons", "n": "Viande hachée", "q": 500, "u": "g"}], "t": "500 g de viande hachée (bœuf ou volaille)"}, {"items": [{"c": "Épicerie", "n": "Tortillas", "q": 1, "u": "paquet"}], "t": "1 paquet de tortillas"}, {"items": [{"c": "Fruits & légumes", "n": "Oignon", "q": 1, "u": ""}], "t": "1 oignon"}, {"items": [{"c": "Fruits & légumes", "n": "Ail", "q": 2, "u": "gousses"}], "t": "2 gousses d''ail"}, {"items": [{"c": "Fruits & légumes", "n": "Poivron rouge", "q": 1, "u": ""}], "t": "1 poivron rouge"}, {"items": [{"c": "Crèmerie & fromages", "n": "Fromage râpé", "q": 150, "u": "g"}], "t": "150 g de fromage râpé (cheddar par exemple)"}, {"items": [{"c": "Épicerie", "n": "Cumin", "q": 1, "u": "c. à soupe"}], "t": "1 c. à soupe de cumin en poudre"}, {"items": [{"c": "Épicerie", "n": "Paprika", "q": 1, "u": "c. à soupe"}], "t": "1 c. à soupe de paprika"}, {"items": [{"c": "Placard", "n": "Huile d''olive", "q": null, "u": ""}], "t": "Un peu d''huile d''olive"}, {"items": [{"c": "Fruits & légumes", "n": "Coriandre", "q": 1, "u": ""}], "t": "1 petite poignée de coriandre fraîche"}, {"items": [{"c": "Placard", "n": "Sel", "q": null, "u": ""}, {"c": "Placard", "n": "Poivre", "q": null, "u": ""}], "t": "Sel et poivre"}]}, {"g": "Pour garnir", "ing": [{"items": [{"c": "Fruits & légumes", "n": "Avocat", "q": null, "u": ""}], "t": "Avocat en morceaux"}, {"items": [{"c": "Épicerie", "n": "Salsa", "q": null, "u": ""}], "t": "Salsa"}, {"items": [{"c": "Crèmerie & fromages", "n": "Crème aigre", "q": null, "u": ""}], "t": "Crème aigre"}]}], "img": "/photos/tacos.jpg", "meta": [["Préparation", "10 min"], ["Cuisson", "20 min"], ["Portions", "4 personnes"]], "notes": ["Matériel : deux poêles (ou une poêle et le micro-ondes).", "Notes : servez les garnitures dans de petites assiettes pour que chacun compose son taco. Le guacamole maison (voir sa fiche) remplace très bien l''avocat en morceaux."], "portions": 4, "ptxt": "4 personnes", "source": "D''après Recette Mexicaine", "steps": ["Émincez l''oignon, hachez l''ail et coupez le poivron en dés.", "Dans une poêle, faites chauffer un peu d''huile d''olive à feu moyen. Faites revenir l''oignon et l''ail jusqu''à ce qu''ils soient dorés, puis ajoutez la viande hachée et faites-la bien dorer.", "Ajoutez le poivron, le cumin, le paprika, un peu de sel et de poivre. Laissez mijoter environ 5 min.", "Pendant ce temps, réchauffez les tortillas quelques secondes dans une autre poêle ou au micro-ondes pour les assouplir.", "Garnissez chaque tortilla de viande, parsemez de fromage râpé, ajoutez des morceaux d''avocat et de la coriandre fraîche.", "Servez avec la salsa et la crème aigre."], "sub": "à la viande hachée et au poivron", "title": "Tacos à la viande hachée"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/tiramisu', '{"alt": "Plat de tiramisu entamé, saupoudré de cacao", "cat": "Desserts", "groups": [{"g": "", "ing": [{"items": [{"c": "Épicerie", "n": "Biscuits à la cuillère", "q": 24, "u": ""}], "t": "24 biscuits à la cuillère"}, {"items": [{"c": "Crèmerie & fromages", "n": "Mascarpone", "q": 250, "u": "g"}], "t": "250 g de mascarpone"}, {"items": [{"c": "Crèmerie & fromages", "n": "Œufs", "q": 3, "u": ""}], "t": "3 œufs"}, {"items": [{"c": "Épicerie", "n": "Sucre roux", "q": 100, "u": "g"}], "t": "100 g de sucre roux"}, {"items": [{"c": "Épicerie", "n": "Sucre vanillé", "q": 1, "u": "sachet"}], "t": "1 sachet de sucre vanillé"}, {"items": [{"c": "Épicerie", "n": "Cacao amer", "q": 30, "u": "g"}], "t": "30 g de cacao amer"}, {"items": [{"c": "Épicerie", "n": "Café", "q": 50, "u": "cl"}], "t": "50 cl de café noir non sucré"}]}], "img": "/photos/tiramisu.jpg", "meta": [["Préparation", "15 min"], ["Repos au frais", "4 h minimum"], ["Portions", "4 personnes"]], "notes": ["Matériel : un saladier, un fouet, une spatule et un plat.", "Notes : dans la recette originale, on ajoute un peu de Marsala sec au café très fort. Version anti-gaspi : remplacez les biscuits par des restes de madeleines ou de brioche un peu sèches."], "portions": 4, "ptxt": "4 personnes", "source": "D''après Marmiton", "steps": ["Séparez les blancs des jaunes d''œufs.", "Mélangez les jaunes avec le sucre roux et le sucre vanillé, puis ajoutez le mascarpone au fouet.", "Montez les blancs en neige et incorporez-les délicatement à la spatule au mélange précédent. Réservez.", "Trempez rapidement les biscuits dans le café et tapissez-en le fond du plat.", "Recouvrez d''une couche de crème au mascarpone, puis alternez couches de biscuits et de crème, en terminant par la crème.", "Saupoudrez de cacao.", "Placez au réfrigérateur au moins 4 h et dégustez bien frais."], "sub": "la recette originale", "title": "Tiramisu"}'::jsonb) on conflict (path) do update set data = excluded.data;
insert into public.docs (path, data) values ('recipes/veloute-courgette', '{"alt": "Bol de velouté de courgette au fromage frais, menthe, ciboulette et graines", "cat": "Soupes & entrées", "groups": [{"g": "", "ing": [{"items": [{"c": "Fruits & légumes", "n": "Courgettes", "q": 6, "u": ""}], "t": "6 courgettes moyennes"}, {"items": [{"c": "Fruits & légumes", "n": "Pomme de terre", "q": 1, "u": ""}], "t": "1 pomme de terre moyenne"}, {"items": [{"c": "Fruits & légumes", "n": "Oignon", "q": 1, "u": ""}], "t": "1 petit oignon"}, {"items": [{"c": "Fruits & légumes", "n": "Ail", "q": 2, "u": "gousses"}], "t": "2 gousses d''ail"}, {"items": [{"c": "Placard", "n": "Eau", "q": 0.5, "u": "l"}], "t": "½ l d''eau"}, {"items": [{"c": "Crèmerie & fromages", "n": "Fromage frais", "q": 2, "u": "c. à soupe"}], "t": "2 c. à soupe de fromage frais de chèvre"}, {"items": [{"c": "Épicerie", "n": "Bouillon de légumes", "q": 1, "u": "cube"}], "t": "1 cube de bouillon de légumes"}, {"items": [{"c": "Fruits & légumes", "n": "Ciboulette", "q": null, "u": ""}], "t": "Quelques brins de ciboulette"}, {"items": [{"c": "Fruits & légumes", "n": "Menthe", "q": null, "u": ""}], "t": "Quelques feuilles de menthe fraîche"}, {"items": [{"c": "Placard", "n": "Huile d''olive", "q": 1, "u": "filet"}], "t": "1 filet d''huile d''olive"}, {"items": [{"c": "Placard", "n": "Poivre", "q": null, "u": ""}], "t": "Poivre du moulin"}]}], "img": "/photos/veloute-courgette.jpg", "meta": [["Préparation", "10 min"], ["Cuisson", "20 min"], ["Portions", "4 personnes"]], "notes": ["Matériel : un faitout et un mixeur plongeant.", "Notes : mixez quelques feuilles de menthe avec le velouté pour plus de fraîcheur. Pour une jolie présentation, déposez une petite cuillère de fromage frais dans chaque bol."], "portions": 4, "ptxt": "4 personnes", "source": "D''après Tangerine Zest", "steps": ["Épluchez l''ail et l''oignon et coupez-les en petits morceaux. Dans un faitout, faites-les revenir 2 min avec un filet d''huile d''olive.", "Versez ½ l d''eau, ajoutez le cube de bouillon et les courgettes coupées en lamelles. Ajoutez la pomme de terre épluchée et coupée en morceaux.", "Faites cuire 20 min à feu moyen.", "En fin de cuisson, mixez bien le tout puis ajoutez le fromage frais et mélangez.", "Servez dans des bols, donnez 2 tours de poivre par bol et parsemez de ciboulette et de menthe ciselées."], "sub": "au fromage frais et à la ciboulette", "title": "Velouté de courgette au fromage frais et à la ciboulette"}'::jsonb) on conflict (path) do update set data = excluded.data;
